{"command":"python3 - << 'PY'
import subprocess, json
def run(inp):
    r=subprocess.run(["./executable",":memory:"], input=inp.encode(), capture_output=True)
    return r.stdout.decode(), r.stderr.decode()
modes=["list","csv","quote","json","html","line","column","box","table","markdown","tabs","ascii","insert","qbox","c","count","jatom","jobject","off","psql","split","tcl","batch","tty"]
for m in modes:
    out,_=run(f".mode {m}\n.mode\n.show\n")
    lines=out.splitlines()
    # show mode line from show
    showmode=[l for l in lines if "mode:" in l]
    print(m, "modecmd:", lines[0] if lines else "", "| show:", showmode[0].strip() if showmode else "", "| hdr:", [l.strip() for l in lines if "headers:" in l])
PY"}

