import subprocess
def show(inp):
    r=subprocess.run(["./executable",":memory:"], input=inp.encode(), capture_output=True)
    d={}
    for l in r.stdout.decode().splitlines():
        if ":" in l:
            k,v=l.rsplit(":",1)
            d[k.strip()]=v.strip()
    return d
