/* escape control chars in a raw string according to g.cfg.escape */
static char *escape_text(const char *s){
  if(!s) return xstrdup("");
  if(g.cfg.escape==ESC_OFF) return xstrdup(s);
  Str r; str_init(&r);
  const char *p=s;
  while(*p){
    unsigned char c=(unsigned char)*p;
    if(c<0x20 && c!='\t' && c!='\n'){
      if(g.cfg.escape==ESC_SYMBOL){
        int cp=0x2400+c;
        if(c==0x7f) cp=0x2421;
