    for(int i=0;i<len;i++){
      unsigned char c=(unsigned char)s[i];
      if(c=='"') str_add(&r,"\\\"");
      else if(c=='\\') str_add(&r,"\\\\");
      else if(c=='\n') str_add(&r,"\\n");
      else if(c=='\r') str_add(&r,"\\r");
      else if(c=='\t') str_add(&r,"\\t");
      else if(c<0x20 || c==0x7f){ char tmp[8]; snprintf(tmp,sizeof(tmp),"\\%03o",c); str_add(&r,tmp); }
      else str_addc(&r,c);
    }
  }
  str_addc(&r,'"');
  return r.buf;
}
static char *html_escape(const char *s){
  Str r; str_init(&r);
  for(const char *p=s;*p;p++){
    if(*p=='<') str_add(&r,"&lt;");
    else if(*p=='>') str_add(&r,"&gt;");
    else if(*p=='&') str_add(&r,"&amp;");
    else if(*p=='"') str_add(&r,"&quot;");
    else if(*p=='\'') str_add(&r,"&#39;");
    else str_addc(&r,*p);
  }
  return r.buf;
}
static int text_looks_numeric(const char *s){
  // trimmed
  while(*s && isspace((unsigned char)*s)) s++;
  size_t n=strlen(s); while(n>0 && isspace((unsigned char)s[n-1])) n--;
  if(n==0) return 0;
  char *tmp=xstrndup(s,n);
  char *end; strtod(tmp,&end);
  int ok = (end && *end==0 && end!=tmp);
  // also integer?
  free(tmp); return ok;
}
static int csv_needs_quote(const char *s,const char *colsep){
  if(!*s) return 1;
  for(const char *p=s;*p;p++){
    char c=*p;
    if(c=='"' || c=='\'' || c=='\n' || c=='\r' || c==' ' || c=='\t') return 1;
    if(colsep && colsep[0] && c==colsep[0]) return 1;
  }
  return 0;
}
static char *apply_char_limit(const char *s){
  // charLimit / titleLimit handling done by caller when needed
  return xstrdup(s?s:"");
}
/* format a cell as display string (allocated) according to current mode settings */
static char *format_cell(Cell *cell,int isHeaderTitle,const char *colName);
static char *format_cell_with_quote(Cell *cell,int quoteOverride,int isHeaderTitle){
  ModeCfg *c=&g.cfg;
  int quote = (quoteOverride>=0? quoteOverride : c->quote);
  if(cell->type==SQLITE_NULL){
    // Special modes decided by caller; here return nullVal
    return xstrdup(c->nullVal);
  }
  if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT){
    return xstrdup(cell->data?cell->data:"");
  }
  if(cell->type==SQLITE_BLOB){
    int len=cell->len; const char *data=cell->data;
    // blobQuote handling
    if(c->blobQuote==BQ_SQL) return sql_quote_text_internal(data,len,1);
    if(c->blobQuote==BQ_HEX) { char *h=hex_encode((unsigned char*)data,len,0); return h; }
    if(c->blobQuote==BQ_TCL) return tcl_quote_bytes(data,len,1);
    if(c->blobQuote==BQ_JSON) return json_quote_text_bytes(data,len,1);
    if(c->blobQuote==BQ_SIZE){ return strdup_printf("(%d-byte blob)",len); }
    if(c->blobQuote==BQ_TEXT){
      char *tmp=xstrndup(data,len); char *z=strchr(tmp,0); (void)z; // truncation will happen in escape?
      // treat as text truncated at NUL
      char *e=escape_text(tmp); free(tmp); return e;
    }
    /* AUTO */
    if(quote==Q_SQL) return sql_quote_text_internal(data,len,1);
    if(quote==Q_JSON) return json_quote_text_bytes(data,len,1);
    if(quote==Q_TCL) {
      // treat blob as text for tcl quoting (not octal)
      // need truncate at NUL? blob bytes may include... use len but tcl_quote_bytes will handle embedded? It loops len.
      // If blob contains NUL, tcl will encode \000
      return tcl_quote_bytes(data,len,0);
    }
    if(quote==Q_CSV){
      // raw text truncated at nul
      char *tmp=xmalloc(len+1); memcpy(tmp,data,len); tmp[len]=0; // trunc at nul by escape
      char *e=escape_text(tmp); free(tmp); return e;
    }
    if(quote==Q_HTML){
      char *tmp=xmalloc(len+1); memcpy(tmp,data,len); tmp[len]=0;
      char *e=html_escape(tmp); free(tmp); return e;
    }
    // off / relaxed
    {
      char *tmp=xmalloc(len+1); memcpy(tmp,data,len); tmp[len]=0;
      if(quote==Q_RELAXED){
        // blob relaxed: if empty -> x'' else sql?
        if(len==0) return xstrdup("x''");
        // printable? use sql quote as original: x'....'
        return sql_quote_text_internal(data,len,1);
      }
      char *e=escape_text(tmp); free(tmp); return e;
    }
  }
  /* TEXT */
  {
    const char *txt=cell->data?cell->data:"";
    // txt may contain embedded NUL in len, but C string handling truncates
    int len = (int)strlen(txt); // truncate at NUL intentionally to match %s behavior
    (void)len;
    if(isHeaderTitle){
      // titles handled elsewhere
    }
    switch(quote){
      case Q_SQL: return sql_quote_text_internal(txt, (int)strlen(txt),0);
      case Q_JSON: return json_quote_text_bytes(txt,(int)strlen(txt),0);
      case Q_TCL: return tcl_quote_bytes(txt,(int)strlen(txt),0);
      case Q_HTML: {
        char *h=html_escape(txt); char *e=escape_text(h); free(h); return e;
      }
      case Q_CSV: {
        if(csv_needs_quote(txt,c->colSep)){
          Str r; str_init(&r); str_addc(&r,'"');
          for(const char *p=txt;*p;p++){ if(*p=='"') str_add(&r,"\"\""); else str_addc(&r,*p); }
          str_addc(&r,'"');
          char *e=escape_text(r.buf); free(r.buf); return e;
          return r.buf;
        }else{
          return escape_text(txt);
        }
      }
      case Q_RELAXED: {
        if(txt[0]==0) return xstrdup("''");
        // whitespace only?
        int allspace=1; for(const char *p=txt;*p;p++) if(!isspace((unsigned char)*p)) allspace=0;
        if(allspace) return sql_quote_text_internal(txt,(int)strlen(txt),0);
        if(text_looks_numeric(txt)) return sql_quote_text_internal(txt,(int)strlen(txt),0);
        return escape_text(txt);
      }
      case Q_OFF:
      default:
        return escape_text(txt);
    }
  }
}
static char *format_cell(Cell *cell,int isHeaderTitle,const char *colName){
  (void)isHeaderTitle; (void)colName;
  return format_cell_with_quote(cell,-1, isHeaderTitle);
}
/* format a title (column name) as text cell according to titleEnc or quote */
static char *format_title(const char *name){
  ModeCfg *c=&g.cfg;
  Cell tmp; tmp.type=SQLITE_TEXT; tmp.data=(char*)name; tmp.len=strlen(name); tmp.subtype=0;
  if(c->titleEnc==TITLE_SQL) { char *r=sql_quote_text_internal(name,strlen(name),0); return r; }
  if(c->titleEnc==TITLE_JSON) return json_quote_text_bytes(name,strlen(name),0);
  if(c->titleEnc==TITLE_TCL) return tcl_quote_bytes(name,strlen(name),0);
  if(c->titleEnc==TITLE_HTML) return html_escape(name);
  if(c->titleEnc==TITLE_CSV){
    // use csv quoting using mode colsep
    Cell cc=tmp; int saved=c->quote; c->quote=Q_CSV; char *r=format_cell_with_quote(&cc,-1,1); c->quote=saved; return r;
  }
  /* TITLE_ON / PLAIN: use mode's normal formatting for a text value, but for some modes titles are plain */
  // For quote/json/c/tcl modes, title formatting follows quote style (as observed: quote mode titles are sql quoted, c titles \"...\", csv titles csv, tcl titles tcl)
  // For columnar/box etc titles are plain (not quoted)
  int mode=c->mode;
  if(mode==M_QUOTE || mode==M_CSV || mode==M_C || mode==M_TCL || mode==M_JATOM || mode==M_LIST){
    // list with quote override etc: if quote off, plain
    return format_cell_with_quote(&tmp,-1,1);
  }
  // plain (escape controls)
  return escape_text(name);
}
C_EOF
"}

