static void lines_add(Lines *L,char *s){ if(L->n>=L->cap){ L->cap=L->cap?L->cap*2:4; L->lines=xrealloc(L->lines,sizeof(char*)*L->cap);} L->lines[L->n++]=s; }
static void lines_free(Lines *L){ for(int i=0;i<L->n;i++) free(L->lines[i]); free(L->lines); }
/* wrap a single logical line (no \n) to width, return segments */
static void wrap_segment(Lines *out,const char *text,int width,int wordwrap){
  if(width<=0){ lines_add(out,xstrdup(text)); return; }
  if(str_width(text)<=width){ lines_add(out,xstrdup(text)); return; }
  const char *p=text;
  while(*p){
    // collect up to width display cols
    const char *q=p; int w=0; const char *lastSpace=0; const char *lastSpaceEnd=0;
    while(*q){
      if(*q==' ') { lastSpace=q; lastSpaceEnd=q+1; }
      int cp; int n=utf8_decode(q,&cp); int cw = cp<32?1:cp_width(cp); if(cp=='\t') cw=1;
      if(w+cw>width) break;
      w+=cw; q+=n;
    }
    if(!*q){ lines_add(out,xstrdup(p)); break; }
    if(wordwrap && lastSpace && lastSpace>p){
