      // skip spaces? wordwrap keeps? Original wordwrap strips leading spaces on next line?
      while(*p==' ') p++;
    }else{
      if(q==p){ int cp; int n=utf8_decode(p,&cp); lines_add(out,xstrndup(p,n)); p+=n; }
      else { lines_add(out,xstrndup(p,q-p)); p=q; }
    }
  }
  if(out->n==0) lines_add(out,xstrdup(""));
}
static void split_cell_lines(Lines *out,const char *text,int width,int wordwrap){
  // split by \n first
  const char *p=text;
  while(1){
    const char *nl=strchr(p,'\n');
    if(!nl){ wrap_segment(out,p,width,wordwrap); break; }
    char *seg=xstrndup(p,nl-p);
    // handle \r? keep?
    wrap_segment(out,seg,width,wordwrap);
    free(seg);
    p=nl+1;
    if(!*p){ /* trailing newline creates an extra empty line? If text ends with \n, original cell ... In column mode test with e\nf: cell split into 2 lines e and f (no trailing) But if ends with newline alone... */
      // If original ends with newline, do not add extra
      break;
    }
  }
}

/* result structure */
typedef struct { char **names; int nCol; Cell **rows; int nRows; int capRows; } Result;
static void result_free(Result *r){
  for(int i=0;i<r->nCol;i++) free(r->names[i]); free(r->names);
  for(int i=0;i<r->nRows;i++){ for(int j=0;j<r->nCol;j++) free(r->rows[i][j].data); free(r->rows[i]); }
  free(r->rows); memset(r,0,sizeof(*r));
}
/* forward */
static void render_result(Result *res);

C_EOF
