  if(c->align && c->align[0]){
    char a=c->align[col];
    if(a=='R'||a=='r') return 2;
    if(a=='C'||a=='c') return 1;
    if(a=='L'||a=='l') return 0;
  }
  if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) return 2;
  return 0;
}
static void render_columnar(Result *res){
  ModeCfg *cfg=&g.cfg;
  int mode=cfg->mode;
  int n=res->nCol;
  if(n<=0) return;
  /* build formatted strings for header and rows */
  char **headers=0;
  if(cfg->showHeader){
    headers=xmalloc(sizeof(char*)*n);
    for(int i=0;i<n;i++) headers[i]=format_title(res->names[i]);
  }
  char ***cells=xmalloc(sizeof(char**)*(res->nRows?res->nRows:1));
  for(int i=0;i<res->nRows;i++){
    cells[i]=xmalloc(sizeof(char*)*n);
    for(int j=0;j<n;j++){
      if(res->rows[i][j].type==SQLITE_NULL && (mode==M_QBOX || mode==M_BOX || mode==M_TABLE || mode==M_MARKDOWN || mode==M_COLUMN || mode==M_SPLIT || mode==M_PSQL)){
        // for these modes null formatting still uses nullVal (empty or NULL for qbox)
        cells[i][j]=xstrdup(cfg->nullVal);
      }else{
        cells[i][j]=format_cell(&res->rows[i][j],0,0);
      }
      /* charLimit */
      if(cfg->charLimit>0 && (int)strlen(cells[i][j])>cfg->charLimit){
        // truncate by characters (display?) simplify byte trunc at limit, but need respect utf8
        // original truncates without ellipsis?
        char *t=cells[i][j]; // cut to charLimit display width?
        int w=0; char *p=t; while(*p){ int cp; int nn=utf8_decode(p,&cp); int cw=cp<32?1:cp_width(cp); if(w+cw>cfg->charLimit) break; w+=cw; p+=nn; }
        char *nt=xstrndup(t,p-t); free(t); cells[i][j]=nt;
      }
      if(cfg->lineLimit>0 && (mode==M_COLUMN || mode==M_BOX || mode==M_TABLE || mode==M_MARKDOWN || mode==M_QBOX || mode==M_PSQL || mode==M_SPLIT)){
        // limit lines: keep first lineLimit lines
        // handled later? Simplistic: count \n
        int cnt=0; char *p=cells[i][j]; char *cut=0;
        for(char *q=p;*q;q++){ if(*q=='\n'){ cnt++; if(cnt>=cfg->lineLimit){ cut=q; break; } } }
        if(cut){ char *nt=xstrndup(p,cut-p); free(cells[i][j]); cells[i][j]=nt; }
      }
    }
  }
  /* widths */
  int *widths=xmalloc(sizeof(int)*n);
  for(int i=0;i<n;i++){
    int w=0;
    if(cfg->widths && i<cfg->nWidths && cfg->widths[i]!=0){
      w=cfg->widths[i]; if(w<0) w=-w;
    }else{
      if(headers) w=str_width(headers[i]);
      for(int r=0;r<res->nRows;r++){
        // width = max line width
        char *txt=cells[r][i];
        const char *p=txt; while(1){ const char *nl=strchr(p,'\n'); if(!nl){ int cw=str_width(p); if(cw>w) w=cw; break; } char *seg=xstrndup(p,nl-p); int cw=str_width(seg); if(cw>w) w=cw; free(seg); p=nl+1; }
      }
      if(w<1) w=1;
    }
    widths[i]=w;
  }
  /* screen width adjustment */
  int sepWidth = (mode==M_COLUMN?2: mode==M_SPLIT?1: 3); // for bordered 3ish (space+bar) approximate compute later
  // compute total
  auto_total:;
  {
    int total=0;
    if(mode==M_COLUMN) { for(int i=0;i<n;i++) total+=widths[i]; total+=2*(n-1); }
    else if(mode==M_SPLIT){ for(int i=0;i<n;i++) total+=widths[i]; total+=1*(n-1); }
    else if(mode==M_BOX || mode==M_QBOX || mode==M_TABLE || mode==M_MARKDOWN){ for(int i=0;i<n;i++) total+=widths[i]+2; total+=n+1; }
    else if(mode==M_PSQL){ for(int i=0;i<n;i++) total+=widths[i]+2; total+=n-1; /* joins */ }
    int sw=cfg->screenWidth;
    if(cfg->screenWidthAuto){
      // determine terminal width: if out is tty use ioctl? simplifying: 80 if not?
      sw=80;
      // if stdout is a tty, could get via TIOCGWINSZ, but non-tty in tests pipe -> 80
      if(isatty(fileno(stdout))){
        // use COLUMNS env?
        const char *col=getenv("COLUMNS"); if(col) sw=atoi(col);
      }
    }
    if(sw>0 && total>sw){
      // reduce widest columns iteratively
      while(total>sw){
        int maxidx=-1; int maxw=0;
        for(int i=0;i<n;i++) if(widths[i]>maxw){ maxw=widths[i]; maxidx=i; }
        if(maxidx<0 || maxw<=1) break;
        widths[maxidx]--; total--;
      }
    }
    (void)sepWidth;
  }
  /* helper to emit a logical row (array of strings, isHeader, alignments per column from cells row index or header centering) */
  // We will implement per style emission inline loops.
  // Pre-split all cells and header into Lines
  Lines *headerLines=0;
  if(headers){
    headerLines=xmalloc(sizeof(Lines)*n);
    for(int i=0;i<n;i++){ memset(&headerLines[i],0,sizeof(Lines)); split_cell_lines(&headerLines[i],headers[i],widths[i],cfg->wordWrap); }
  }
  Lines **rowLines=xmalloc(sizeof(Lines*)*(res->nRows?res->nRows:1));
  for(int r=0;r<res->nRows;r++){
    rowLines[r]=xmalloc(sizeof(Lines)*n);
    for(int i=0;i<n;i++){ memset(&rowLines[r][i],0,sizeof(Lines)); split_cell_lines(&rowLines[r][i],cells[r][i],widths[i],cfg->wordWrap); }
  }
  Str outLine; str_init(&outLine);
  #define EMIT_LINE(s) do{ out_str(s); out_str(cfg->rowSep); }while(0)
  // border lines for box/table
  if(mode==M_BOX || mode==M_QBOX){
    if(cfg->border){
      str_clear(&outLine); str_add(&outLine,"╭");
      for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_add(&outLine,"─"); if(i<n-1) str_add(&outLine,"┬"); }
      str_add(&outLine,"╮"); EMIT_LINE(outLine.buf);
    }
  }else if(mode==M_TABLE){
    if(cfg->border){
      str_clear(&outLine); str_addc(&outLine,'+');
      for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); if(i<n-1) str_addc(&outLine,'+'); }
      str_addc(&outLine,'+'); EMIT_LINE(outLine.buf);
    }
  }
  // function-like inline for a logical row:
  // We'll write a loop over logical rows: -1 = header, else row index
  for(int logical=-1; logical<res->nRows; logical++){
    if(logical==-1 && !headers) continue;
    Lines *linesArr = (logical==-1? headerLines : rowLines[logical]);
    int maxLines=1; for(int i=0;i<n;i++) if(linesArr[i].n>maxLines) maxLines=linesArr[i].n;
    for(int sub=0; sub<maxLines; sub++){
      str_clear(&outLine);
      if(mode==M_BOX || mode==M_QBOX || mode==M_TABLE){
        char vbar = (mode==M_TABLE?'|':'│');
        // actually box uses multibyte
        if(cfg->border){
          if(mode==M_TABLE) str_addc(&outLine,'|'); else str_add(&outLine,"│");
        }
        for(int i=0;i<n;i++){
          const char *seg = sub < linesArr[i].n ? linesArr[i].lines[sub] : "";
          int align;
          if(logical==-1) align=1;
          else align=cell_alignment(&res->rows[logical][i],i);
          char *padded=pad_str(seg,widths[i],align);
          str_addc(&outLine,' '); str_add(&outLine,padded); str_addc(&outLine,' '); free(padded);
          if(i<n-1){ if(cfg->border){ if(mode==M_TABLE) str_addc(&outLine,'|'); else str_add(&outLine,"│"); } }
          else { if(cfg->border){ if(mode==M_TABLE) str_addc(&outLine,'|'); else str_add(&outLine,"│"); } else {
            // border off: rtrim later
          } }
          (void)vbar;
        }
        if(!cfg->border){
          char *t=rtrim_dup(outLine.buf); out_str(t); out_str(cfg->rowSep); free(t);
        }else{
          EMIT_LINE(outLine.buf);
        }
      }else if(mode==M_MARKDOWN){
        str_addc(&outLine,'|');
        for(int i=0;i<n;i++){
          const char *seg = sub < linesArr[i].n ? linesArr[i].lines[sub] : "";
          int align = (logical==-1?1:cell_alignment(&res->rows[logical][i],i));
          char *padded=pad_str(seg,widths[i],align);
          str_addc(&outLine,' '); str_add(&outLine,padded); str_addc(&outLine,' '); free(padded);
          str_addc(&outLine,'|');
        }
        EMIT_LINE(outLine.buf);
      }else if(mode==M_PSQL){
        for(int i=0;i<n;i++){
          const char *seg = sub < linesArr[i].n ? linesArr[i].lines[sub] : "";
          int align = (logical==-1?1:cell_alignment(&res->rows[logical][i],i));
          char *padded=pad_str(seg,widths[i],align);
          str_addc(&outLine,' '); str_add(&outLine,padded); str_addc(&outLine,' '); free(padded);
          if(i<n-1) str_addc(&outLine,'|');
        }
        char *t=rtrim_dup(outLine.buf); out_str(t); out_str(cfg->rowSep); free(t);
      }else{ /* column / split */
        const char *sep = (mode==M_SPLIT?" ":"  ");
        for(int i=0;i<n;i++){
          const char *seg = sub < linesArr[i].n ? linesArr[i].lines[sub] : "";
          int align = (logical==-1?1:cell_alignment(&res->rows[logical][i],i));
          char *padded=pad_str(seg,widths[i],align);
          str_add(&outLine,padded); free(padded);
          if(i<n-1) str_add(&outLine,sep);
        }
        char *t=rtrim_dup(outLine.buf); out_str(t); out_str(cfg->rowSep); free(t);
      }
    }
    // after header, separator line
    if(logical==-1 && headers){
      str_clear(&outLine);
      if(mode==M_BOX || mode==M_QBOX){
        if(cfg->border){
          str_add(&outLine,"╞");
          for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_add(&outLine,"═"); if(i<n-1) str_add(&outLine,"╪"); }
          str_add(&outLine,"╡"); EMIT_LINE(outLine.buf);
        }else{
          // border off separator: "═══" segments joined? Original: just segments with? For single col it printed ═══ . For multi, likely segments separated by space?
          for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_add(&outLine,"═"); if(i<n-1) str_addc(&outLine,' '); }
          char *t=rtrim_dup(outLine.buf); out_str(t); out_str(cfg->rowSep); free(t);
        }
      }else if(mode==M_TABLE){
        if(cfg->border){
          str_addc(&outLine,'+');
          for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); if(i<n-1) str_addc(&outLine,'+'); }
          str_addc(&outLine,'+'); EMIT_LINE(outLine.buf);
        }else{
          for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); if(i<n-1) str_addc(&outLine,' '); }
          char *t=rtrim_dup(outLine.buf); out_str(t); out_str(cfg->rowSep); free(t);
        }
      }else if(mode==M_MARKDOWN){
        str_addc(&outLine,'|');
        for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); str_addc(&outLine,'|'); }
        EMIT_LINE(outLine.buf);
      }else if(mode==M_PSQL){
        for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); if(i<n-1) str_addc(&outLine,'+'); }
        EMIT_LINE(outLine.buf);
      }else{
        const char *sep = (mode==M_SPLIT?" ":"  ");
        for(int i=0;i<n;i++){ for(int k=0;k<widths[i];k++) str_addc(&outLine,'-'); if(i<n-1) str_add(&outLine,sep); }
        EMIT_LINE(outLine.buf);
      }
    }
  }
  // bottom border
  if(mode==M_BOX || mode==M_QBOX){
    if(cfg->border){
      str_clear(&outLine); str_add(&outLine,"╰");
      for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_add(&outLine,"─"); if(i<n-1) str_add(&outLine,"┴"); }
      str_add(&outLine,"╯"); EMIT_LINE(outLine.buf);
    }
  }else if(mode==M_TABLE){
    if(cfg->border){
      str_clear(&outLine); str_addc(&outLine,'+');
      for(int i=0;i<n;i++){ for(int k=0;k<widths[i]+2;k++) str_addc(&outLine,'-'); if(i<n-1) str_addc(&outLine,'+'); }
      str_addc(&outLine,'+'); EMIT_LINE(outLine.buf);
    }
  }
  #undef EMIT_LINE
  // cleanup
  str_free(&outLine);
  if(headers){ for(int i=0;i<n;i++){ free(headers[i]); lines_free(&headerLines[i]); } free(headers); free(headerLines); }
  for(int r=0;r<res->nRows;r++){ for(int i=0;i<n;i++){ free(cells[r][i]); lines_free(&rowLines[r][i]); } free(cells[r]); free(rowLines[r]); }
  free(cells); free(rowLines); free(widths);
}

static void render_result(Result *res){
  ModeCfg *cfg=&g.cfg;
  int mode=cfg->mode;
  if(mode==M_OFF) return;
  if(mode==M_COUNT){
    out_printf("%d",res->nRows);
    out_str(cfg->rowSep);
    return;
  }
  if(res->nCol<=0) return;
  if(res->nRows<=0) return;
  // columnar family
  if(mode==M_COLUMN || mode==M_BOX || mode==M_TABLE || mode==M_MARKDOWN || mode==M_QBOX || mode==M_PSQL || mode==M_SPLIT){
    render_columnar(res);
    return;
  }
  if(mode==M_JSON){
    out_str("[");
    for(int r=0;r<res->nRows;r++){
      if(r>0) out_str(",\n");
      out_str("{");
      for(int i=0;i<res->nCol;i++){
        if(i>0) out_str(",");
        char *k=json_quote_text_bytes(res->names[i],strlen(res->names[i]),0);
        out_str(k); free(k); out_str(":");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) out_str(cell->data);
        else if(cell->type==SQLITE_BLOB){ char *v=json_quote_text_bytes(cell->data,cell->len,1); out_str(v); free(v); }
        else { char *v=json_quote_text_bytes(cell->data,strlen(cell->data),0); out_str(v); free(v); }
      }
      out_str("}");
    }
    out_str("]");
    out_str(cfg->rowSep);
    return;
  }
  if(mode==M_JOBJECT){
    for(int r=0;r<res->nRows;r++){
      out_str("{");
      for(int i=0;i<res->nCol;i++){
        if(i>0) out_str(",");
        char *k=json_quote_text_bytes(res->names[i],strlen(res->names[i]),0);
        out_str(k); free(k); out_str(":");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) out_str(cell->data);
        else if(cell->type==SQLITE_BLOB){ char *v=json_quote_text_bytes(cell->data,cell->len,1); out_str(v); free(v); }
        else { char *v=json_quote_text_bytes(cell->data,strlen(cell->data),0); out_str(v); free(v); }
      }
      out_str("}");
      out_str(cfg->rowSep);
    }
    return;
  }
  if(mode==M_HTML){
    if(cfg->showHeader){
      out_str("<TR>\n");
      for(int i=0;i<res->nCol;i++){ out_str("<TH>"); char *h=html_escape(res->names[i]); out_str(h); free(h); out_str("\n"); }
      out_str("</TR>\n");
    }
    for(int r=0;r<res->nRows;r++){
      out_str("<TR>\n");
      for(int i=0;i<res->nCol;i++){
        out_str("<TD>");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else { char *v=format_cell(cell,0,0); out_str(v); free(v); }
        out_str("\n");
      }
      out_str("</TR>\n");
    }
    return;
  }
  if(mode==M_LINE){
    // label width
    int lw=0; for(int i=0;i<res->nCol;i++){ int w=str_width(res->names[i]); if(w>lw) lw=w; }
    for(int r=0;r<res->nRows;r++){
      if(r>0) out_str("\n");
      for(int i=0;i<res->nCol;i++){
        char *v;
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) v=xstrdup(cfg->nullVal);
        else v=format_cell(cell,0,0);
        // split v by \n
        const char *p=v; int first=1;
        while(1){
          const char *nl=strchr(p,'\n');
          char *seg = nl? xstrndup(p,nl-p) : xstrdup(p);
          if(first){
            // right align label
            int pad=lw - str_width(res->names[i]); for(int k=0;k<pad;k++) out_str(" ");
            out_str(res->names[i]); out_str(cfg->colSep); out_str(seg);
            out_str("\n");
            first=0;
          }else{
            int pad=lw + (int)strlen(cfg->colSep); for(int k=0;k<pad;k++) out_str(" ");
            out_str(seg); out_str("\n");
          }
          free(seg);
          if(!nl) break;
          p=nl+1;
          if(!*p) break;
        }
        free(v);
      }
    }
    return;
  }
  if(mode==M_INSERT){
    const char *table = cfg->tablename && cfg->tablename[0] ? cfg->tablename : "tab";
    char *tblq=quote_ident(table);
    // multiInsert handling
    Str curStmt; str_init(&curStmt); int curTuples=0;
    for(int r=0;r<res->nRows;r++){
      // build tuple
      Str tuple; str_init(&tuple); str_addc(&tuple,'(');
      for(int i=0;i<res->nCol;i++){
        if(i) str_addc(&tuple,',');
        char *v=sql_format_value(&res->rows[r][i]); str_add(&tuple,v); free(v);
      }
      str_addc(&tuple,')');
      if(cfg->multiInsert>0){
        Str header; str_init(&header); str_add(&header,"INSERT INTO "); str_add(&header,tblq);
        if(cfg->showHeader){
          str_addc(&header,'(');
          for(int i=0;i<res->nCol;i++){ if(i) str_addc(&header,','); char *qid=quote_ident(res->names[i]); str_add(&header,qid); free(qid); }
          str_addc(&header,')');
        }
        str_add(&header," VALUES");
        if(curTuples==0){
          str_clear(&curStmt); str_add(&curStmt,header.buf); str_add(&curStmt,tuple.buf);
          curTuples=1;
        }else{
          // check length if adding would exceed
          size_t prospective = curStmt.len + 2 + 2 + tuple.len; // ",\n  " (?) approximate
          if((int)prospective > cfg->multiInsert){
            // flush
            str_add(&curStmt,";\n"); out_str(curStmt.buf);
            str_clear(&curStmt); str_add(&curStmt,header.buf); str_add(&curStmt,tuple.buf);
            curTuples=1;
          }else{
            str_add(&curStmt,",\n  "); str_add(&curStmt,tuple.buf);
            curTuples++;
          }
        }
        str_free(&header);
        if(r==res->nRows-1 && curTuples>0){ str_add(&curStmt,";\n"); out_str(curStmt.buf); }
      }else{
        out_str("INSERT INTO "); out_str(tblq);
        if(cfg->showHeader){
          out_str("(");
          for(int i=0;i<res->nCol;i++){ if(i) out_str(","); char *qid=quote_ident(res->names[i]); out_str(qid); free(qid); }
          out_str(")");
        }
        out_str(" VALUES"); out_str(tuple.buf); out_str(";\n");
      }
      str_free(&tuple);
    }
    str_free(&curStmt);
    free(tblq);
    return;
  }
  /* delimited modes: list, csv, quote, c, jatom, tcl, tabs, ascii */
  {
    if(cfg->showHeader){
      for(int i=0;i<res->nCol;i++){
        if(i) out_str(cfg->colSep);
        char *t=format_title(res->names[i]); out_str(t); free(t);
      }
      out_str(cfg->rowSep);
    }
    for(int r=0;r<res->nRows;r++){
      for(int i=0;i<res->nCol;i++){
        if(i) out_str(cfg->colSep);
        char *v=format_cell(&res->rows[r][i],0,0);
        out_str(v); free(v);
      }
      out_str(cfg->rowSep);
    }
    return;
  }
}
