static int cell_alignment(Cell *cell,int col){
  ModeCfg *c=&g.cfg;
  if(c->align && c->align[0]){
    char a=c->align[col];
    if(a=='R'||a=='r') return 2;
    if(a=='C'||a=='c') return 1;
    if(a=='L'||a=='l') return 0;
  }
  if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) return 2;
  return 0;
}
static void render_columnar(Result *res){
  ModeCfg *cfg=&g.cfg;
