static void render_result(Result *res){
  ModeCfg *cfg=&g.cfg;
  int mode=cfg->mode;
  if(mode==M_OFF) return;
  if(mode==M_COUNT){
    out_printf("%d",res->nRows);
    out_str(cfg->rowSep);
    return;
  }
  if(res->nCol<=0) return;
  if(res->nRows<=0) return;
  // columnar family
  if(mode==M_COLUMN || mode==M_BOX || mode==M_TABLE || mode==M_MARKDOWN || mode==M_QBOX || mode==M_PSQL || mode==M_SPLIT){
    render_columnar(res);
    return;
  }
  if(mode==M_JSON){
    out_str("[");
    for(int r=0;r<res->nRows;r++){
      if(r>0) out_str(",\n");
      out_str("{");
      for(int i=0;i<res->nCol;i++){
        if(i>0) out_str(",");
        char *k=json_quote_text_bytes(res->names[i],strlen(res->names[i]),0);
        out_str(k); free(k); out_str(":");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) out_str(cell->data);
        else if(cell->type==SQLITE_BLOB){ char *v=json_quote_text_bytes(cell->data,cell->len,1); out_str(v); free(v); }
        else { char *v=json_quote_text_bytes(cell->data,strlen(cell->data),0); out_str(v); free(v); }
      }
      out_str("}");
    }
    out_str("]");
    out_str(cfg->rowSep);
    return;
  }
  if(mode==M_JOBJECT){
    for(int r=0;r<res->nRows;r++){
      out_str("{");
      for(int i=0;i<res->nCol;i++){
        if(i>0) out_str(",");
        char *k=json_quote_text_bytes(res->names[i],strlen(res->names[i]),0);
        out_str(k); free(k); out_str(":");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else if(cell->type==SQLITE_INTEGER || cell->type==SQLITE_FLOAT) out_str(cell->data);
        else if(cell->type==SQLITE_BLOB){ char *v=json_quote_text_bytes(cell->data,cell->len,1); out_str(v); free(v); }
        else { char *v=json_quote_text_bytes(cell->data,strlen(cell->data),0); out_str(v); free(v); }
      }
      out_str("}");
      out_str(cfg->rowSep);
    }
    return;
  }
  if(mode==M_HTML){
    if(cfg->showHeader){
      out_str("<TR>\n");
      for(int i=0;i<res->nCol;i++){ out_str("<TH>"); char *h=html_escape(res->names[i]); out_str(h); free(h); out_str("\n"); }
      out_str("</TR>\n");
    }
    for(int r=0;r<res->nRows;r++){
      out_str("<TR>\n");
      for(int i=0;i<res->nCol;i++){
        out_str("<TD>");
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) out_str("null");
        else { char *v=format_cell(cell,0,0); out_str(v); free(v); }
        out_str("\n");
      }
      out_str("</TR>\n");
    }
    return;
  }
  if(mode==M_LINE){
    // label width
    int lw=0; for(int i=0;i<res->nCol;i++){ int w=str_width(res->names[i]); if(w>lw) lw=w; }
    for(int r=0;r<res->nRows;r++){
      if(r>0) out_str("\n");
      for(int i=0;i<res->nCol;i++){
        char *v;
        Cell *cell=&res->rows[r][i];
        if(cell->type==SQLITE_NULL) v=xstrdup(cfg->nullVal);
        else v=format_cell(cell,0,0);
        // split v by \n
        const char *p=v; int first=1;
        while(1){
          const char *nl=strchr(p,'\n');
          char *seg = nl? xstrndup(p,nl-p) : xstrdup(p);
          if(first){
            // right align label
            int pad=lw - str_width(res->names[i]); for(int k=0;k<pad;k++) out_str(" ");
            out_str(res->names[i]); out_str(cfg->colSep); out_str(seg);
            out_str("\n");
            first=0;
          }else{
            int pad=lw + (int)strlen(cfg->colSep); for(int k=0;k<pad;k++) out_str(" ");
            out_str(seg); out_str("\n");
          }
          free(seg);
          if(!nl) break;
          p=nl+1;
          if(!*p) break;
        }
        free(v);
      }
    }
    return;
  }
  if(mode==M_INSERT){
    const char *table = cfg->tablename && cfg->tablename[0] ? cfg->tablename : "tab";
    char *tblq=quote_ident(table);
    // multiInsert handling
    Str curStmt; str_init(&curStmt); int curTuples=0;
    for(int r=0;r<res->nRows;r++){
      // build tuple
      Str tuple; str_init(&tuple); str_addc(&tuple,'(');
      for(int i=0;i<res->nCol;i++){
        if(i) str_addc(&tuple,',');
        char *v=sql_format_value(&res->rows[r][i]); str_add(&tuple,v); free(v);
      }
      str_addc(&tuple,')');
      if(cfg->multiInsert>0){
        Str header; str_init(&header); str_add(&header,"INSERT INTO "); str_add(&header,tblq);
        if(cfg->showHeader){
          str_addc(&header,'(');
          for(int i=0;i<res->nCol;i++){ if(i) str_addc(&header,','); char *qid=quote_ident(res->names[i]); str_add(&header,qid); free(qid); }
          str_addc(&header,')');
        }
        str_add(&header," VALUES");
        if(curTuples==0){
          str_clear(&curStmt); str_add(&curStmt,header.buf); str_add(&curStmt,tuple.buf);
          curTuples=1;
        }else{
          // check length if adding would exceed
          size_t prospective = curStmt.len + 2 + 2 + tuple.len; // ",\n  " (?) approximate
          if((int)prospective > cfg->multiInsert){
            // flush
            str_add(&curStmt,";\n"); out_str(curStmt.buf);
            str_clear(&curStmt); str_add(&curStmt,header.buf); str_add(&curStmt,tuple.buf);
            curTuples=1;
          }else{
            str_add(&curStmt,",\n  "); str_add(&curStmt,tuple.buf);
            curTuples++;
          }
        }
        str_free(&header);
        if(r==res->nRows-1 && curTuples>0){ str_add(&curStmt,";\n"); out_str(curStmt.buf); }
      }else{
        out_str("INSERT INTO "); out_str(tblq);
        if(cfg->showHeader){
          out_str("(");
          for(int i=0;i<res->nCol;i++){ if(i) out_str(","); char *qid=quote_ident(res->names[i]); out_str(qid); free(qid); }
          out_str(")");
        }
        out_str(" VALUES"); out_str(tuple.buf); out_str(";\n");
      }
      str_free(&tuple);
    }
    str_free(&curStmt);
    free(tblq);
    return;
  }
  /* delimited modes: list, csv, quote, c, jatom, tcl, tabs, ascii */
  {
    if(cfg->showHeader){
      for(int i=0;i<res->nCol;i++){
        if(i) out_str(cfg->colSep);
        char *t=format_title(res->names[i]); out_str(t); free(t);
      }
      out_str(cfg->rowSep);
    }
    for(int r=0;r<res->nRows;r++){
      for(int i=0;i<res->nCol;i++){
        if(i) out_str(cfg->colSep);
        char *v=format_cell(&res->rows[r][i],0,0);
        out_str(v); free(v);
      }
      out_str(cfg->rowSep);
    }
    return;
  }
}
C_EOF
