    }
    if(p[0]=='-' && p[1]=='-'){ while(*p && *p!='\n') p++; continue; }
    if(p[0]=='/' && p[1]=='*'){ p+=2; while(*p && !(p[0]=='*' && p[1]=='/')) p++; if(*p) p+=2; continue; }
    if(is_token_char(*p)){
      const char *start=p; while(*p && is_token_char(*p)) p++;
      size_t len=p-start;
      if(len==nlen && strncasecmp(start,name,nlen)==0) return (int)(start-text);
      continue;
    }
    p++;
  }
  return -1;
}
static int compute_error_offset(const char *residual,const char *msg){
  // no caret messages
  if(starts_ci(msg,"no such table:")||starts_ci(msg,"no such view:")||starts_ci(msg,"no such index:")||starts_ci(msg,"no such trigger:")||starts_ci(msg,"no such module:")) return -1;
  if(strstr(msg,"values were supplied")) return -1;
  if(strstr(msg,"ORDER BY term out of range")||strstr(msg,"GROUP BY term out of range")) return -1;
  if(starts_ci(msg,"object name reserved")) return -1;
  // near "TOKEN"
  if(starts_ci(msg,"near \"")){
    const char *a=strchr(msg,'"'); const char *b=a?strchr(a+1,'"'):0;
    if(a && b){
      char *tok=xstrndup(a+1,b-a-1);
      int off=-1;
      // punctuation token: find exact char token search as substring (first)
      // identifiers: find token as identifier
      // First try substring exact (for tokens like ";"?? may appear many)
      // Prefer identifier search if token is word
      int allword=1; for(char *p=tok;*p;p++) if(!is_token_char(*p)) allword=0;
      if(allword) off=find_identifier_token(residual,tok);
      else {
        // find token as substring but skipping strings? fallback substring
        off=find_token_substring(residual,tok);
        // Special: token ";" or ")" etc first substring is likely correct in many cases. However if token is ")" and there is "(" before, substring finds closing? There is only closing characters in text, fine.
      }
      free(tok); return off;
    }
  }
  if(starts_ci(msg,"unrecognized token:")){
    const char *a=strchr(msg,'"'); if(!a) return -1;
    // token content until last quote? Message format: unrecognized token: "TOKEN"
    const char *last=strrchr(msg,'"'); if(last<=a) return -1;
    char *tok=xstrndup(a+1,last-a-1);
    int off=find_token_substring(residual,tok);
    if(off<0){
      // find first char of token
      // token might contain newline represented as actual newline in msg but residual newline flattened? original token: "'unclosed;\nselect..." Search for prefix up to first (maybe 8 chars)
      size_t tl=strlen(tok); size_t tryLen= tl>10?10:tl;
      while(tryLen>0){
        char *prefix=xstrndup(tok,tryLen);
        off=find_token_substring(residual,prefix);
        free(prefix); if(off>=0) break; tryLen--;
      }
    }
    if(off<0 && tok[0]){
      // find occurrence of first character as token start (e.g. ' , " , [ , :)
      char tmp[2]={tok[0],0}; off=find_token_substring(residual,tmp);
    }
    free(tok); return off;
  }
  // no such column: NAME  / ambiguous column name: NAME / no such function: NAME
  const char *colon=0;
  int isColumn=0;
  if(starts_ci(msg,"no such column:")) { colon=strchr(msg,':'); isColumn=1; }
  else if(starts_ci(msg,"ambiguous column name:")) { colon=strchr(msg,':'); isColumn=1; }
  else if(starts_ci(msg,"no such function:")) { colon=strchr(msg,':'); isColumn=1; }
  else if(strstr(msg,"already exists")){
    // extract object name: words: type name already...
    // find CREATE ...name
    // tokenize residual: look for create then next non-keyword token
    // Simple: find object name by parsing msg: second word
    char *copy=xstrdup(msg);
    char *save=0; char *w1=strtok_r(copy," ",&save); char *w2=strtok_r(NULL," ",&save); (void)w1;
    int off=-1;
    if(w2){
      // Find w2 as identifier after a create keyword: search all identifier tokens and prefer one after "table/index/view/trigger"
      // Fallback identifier search
      off=find_identifier_token(residual,w2);
      // Prefer second occurrence? For "create table t(a); create ... handled by per statement residual contains only that statement, first identifier t is column? create table t: tokens: create, table, t -> identifier search finds t at correct place (first distinct)
      // If table name appears as column name earlier, risk low.
    }
    free(copy); return off;
  }
  if(isColumn && colon){
    const char *p=colon+1; while(*p==' ') p++;
    // name up to " -" or end
    const char *end=strstr(p," - "); size_t n = end? (size_t)(end-p): strlen(p);
    char *name=xstrndup(p,n);
    // trim trailing spaces
    while(n>0 && isspace((unsigned char)name[n-1])) name[--n]=0;
    int off=-1;
    // If name contains '.' or quotes, substring search first
    if(strchr(name,'.') || strchr(name,'"') || strchr(name,'\'')){
      off=find_token_substring(residual,name);
      if(off<0){
        // try stripped quotes
        // remove quotes from name
        Str tmp; str_init(&tmp); for(char *q=name;*q;q++) if(*q!='"' && *q!='\'') str_addc(&tmp,*q);
        off=find_identifier_token(residual,tmp.buf); str_free(&tmp);
      }
    }
    if(off<0) off=find_identifier_token(residual,name);
    if(off<0) off=find_token_substring(residual,name);
    free(name); return off;
  }
  return -1;
}
static void print_sql_error(int isParse,const char *msg,const char *residual,int stmtLine,SrcCtx *ctx){
  // Prefix
  if(ctx && ctx->kind==2){
    fprintf(stderr,"%s in %d%s command line argument: %s\n", isParse?"Parse error":"Error", ctx->argIndex, ordinal_suffix(ctx->argIndex), msg);
  }else if(ctx && ctx->kind==1 && ctx->filename){
    fprintf(stderr,"%s near line %d of %s: %s\n", isParse?"Parse error":"Error", stmtLine, ctx->filename, msg);
  }else{
    fprintf(stderr,"%s near line %d: %s\n", isParse?"Parse error":"Error", stmtLine, msg);
  }
  if(!isParse) return;
  int off=compute_error_offset(residual,msg);
  if(off<0) return;
  // Flatten residual
  Str flat; str_init(&flat);
  for(const char *p=residual;*p;p++){
    char c=*p; if(c=='\n'||c=='\r'||c=='\t'||c=='\v'||c=='\f') str_addc(&flat,' '); else str_addc(&flat,c);
  }
  // trim leading spaces
  int trim=0; while(flat.buf[trim]==' ') trim++;
  int offDisp=off-trim; if(offDisp<0) offDisp=0;
  const char *disp=flat.buf+trim; int dispLen=strlen(disp);
  int windowStart=0;
  if(dispLen>78 && offDisp>50) windowStart=offDisp-50;
  int windowLen=dispLen-windowStart; if(windowLen>78) windowLen=78;
  fprintf(stderr,"  %.*s\n", windowLen, disp+windowStart);
  int caretIdx=2+(offDisp-windowStart);
  const char *marker="error here";
  if(caretIdx>=27){
    // flipped: marker text "error here ---^" length 15, caret at end
    int spaces=caretIdx - ((int)strlen(marker)+4); // marker+space+3 dashes =? "error here ---^" =10+1+3+1=15, last index14
    if(spaces<0) spaces=0;
    fprintf(stderr,"%*s%s ---^\n", spaces, "", marker);
  }else{
    fprintf(stderr,"%*s^--- %s\n", caretIdx, "", marker);
  }
  str_free(&flat);
}
static int first_token_line_offset(const char *sql,const char *p){
  // count newlines in sql[0..p) plus in residual up to first nonspace/semicolon char
  int cnt=0;
  // caller will compute base; this helper returns additional newlines in residual before first token
  const char *q=p;
  while(*q){
    if(*q=='\n'){ cnt++; q++; continue; }
    if(isspace((unsigned char)*q) || *q==';'){ q++; continue; }
    break;
  }
  return cnt;
}
static int count_newlines(const char *s,size_t n){ int c=0; for(size_t i=0;i<n;i++) if(s[i]=='\n') c++; return c; }
/* determine first keywords */
static void first_keywords(const char *sql,char *kw1,char *kw2,char *kw3){
  kw1[0]=kw2[0]=kw3[0]=0;
  const char *p=sql;
  char *outs[3]={kw1,kw2,kw3};
  for(int idx=0;idx<3;idx++){
    // skip ws and comments and semicolons
    while(1){
      while(*p && (isspace((unsigned char)*p)||*p==';')) p++;
      if(p[0]=='-' && p[1]=='-'){ while(*p && *p!='\n') p++; continue; }
      if(p[0]=='/' && p[1]=='*'){ p+=2; while(*p && !(p[0]=='*'&&p[1]=='/')) p++; if(*p) p+=2; continue; }
      break;
    }
    int i=0; while(*p && isalpha((unsigned char)*p) && i<31){ outs[idx][i++]=toupper((unsigned char)*p); p++; }
    outs[idx][i]=0;
    if(!*p) break;
  }
}
static void apply_params(sqlite3_stmt *stmt){
  for(int i=0;i<g.nParams;i++){
    int idx=sqlite3_bind_parameter_index(stmt,g.params[i].name);
    if(idx>0){
      if(g.params[i].isNull) sqlite3_bind_null(stmt,idx);
      else sqlite3_bind_text(stmt,idx,g.params[i].value,-1,SQLITE_TRANSIENT);
    }
  }
}
/* forward for render_explain and eqp */
static void render_explain_result(Result *res);
static void render_query_plan_result(Result *res);
static void show_stats_after_stmt(sqlite3_stmt *stmt,int isStmtStats);
static int exec_sql_chunk(const char *sql,int startLine,SrcCtx *ctx);
static int exec_single_statement_internal(const char *sqlText); // for internal queries: prepare/step and collect, not used here

/* Main SQL chunk execution: returns 0 ok, 1 if error encountered */
static int exec_sql_chunk(const char *sql,int startLine,SrcCtx *ctx){
  if(!g.db){
    // try open ??? If no db, treat as error?
    fprintf(stderr,"Error: no database open\n"); return 1;
  }
  const char *p=sql;
  int hadError=0;
  // timers for whole chunk? timer per statement
  while(*p){
    // skip leading whitespace only for emptiness check; but prepare handles
    const char *tmp=p; while(*tmp && isspace((unsigned char)*tmp)) tmp++;
    if(!*tmp) break;
    sqlite3_stmt *stmt=0; const char *tail=0;
    int rc=sqlite3_prepare_v2(g.db,p,-1,&stmt,&tail);
    if(rc!=SQLITE_OK){
      const char *msg=sqlite3_errmsg(g.db);
      // compute stmt line: startLine + newlines before p + first token additional
      int line = startLine + count_newlines(sql, (size_t)(p-sql)) + first_token_line_offset(sql,p);
      // Adjust: if the first token is after a newline that is counted in count_newlines before p? p may point right after prior ; before newline, so additional counts residual whitespace newlines.
      // If statement is on same line etc it's fine.
      char *msgCopy=xstrdup(msg);
      print_sql_error(1,msgCopy,p,line,ctx);
      free(msgCopy);
      hadError=1;
      if(ctx && !ctx->countErrors){
        // startup: don't mark global except if bail causes
        if(g.bail && ctx->bailCounts) g.encounteredError=1;
      }else{
        g.encounteredError=1;
      }
      if(stmt) sqlite3_finalize(stmt);
      break;
    }
    if(!stmt){
      if(!tail || tail==p) break;
      p=tail;
      continue;
    }
    // statement text segment
    char *stmtText = xstrndup(p, tail? (size_t)(tail-p): strlen(p));
    char kw1[32],kw2[32],kw3[32]; first_keywords(stmtText,kw1,kw2,kw3);
    int isExplain = (strcmp(kw1,"EXPLAIN")==0);
    int isExplainQP = isExplain && (strcmp(kw2,"QUERY")==0);
    // compile_options interception for fidelity
    // Detect PRAGMA compile_options (simple)
    int isCompileOptions=0;
    if(strcmp(kw1,"PRAGMA")==0 && strcmp(kw2,"COMPILE_OPTIONS")==0) isCompileOptions=1;
    // Timer start
    struct timeval tvStart; gettimeofday(&tvStart,NULL);
    struct rusage ruStart; getrusage(RUSAGE_SELF,&ruStart);
    // EQP handling
    if(g.eqp!=0 && !isExplain){
      if(!strcmp(kw1,"SELECT")||!strcmp(kw1,"VALUES")||!strcmp(kw1,"INSERT")||!strcmp(kw1,"UPDATE")||!strcmp(kw1,"DELETE")||!strcmp(kw1,"WITH")||!strcmp(kw1,"REPLACE")){
        // build explain query plan
        // strip trailing semicolon/space from stmtText for safety (keep as is, EXPLAIN QUERY PLAN <stmt>; works)
        char *eqpSql = strdup_printf("EXPLAIN QUERY PLAN %s", stmtText);
        sqlite3_stmt *est=0; const char *etail=0;
        if(sqlite3_prepare_v2(g.db,eqpSql,-1,&est,&etail)==SQLITE_OK && est){
          Result er; memset(&er,0,sizeof(er)); er.nCol=sqlite3_column_count(est); er.names=xmalloc(sizeof(char*)*(er.nCol?er.nCol:1)); for(int i=0;i<er.nCol;i++) er.names[i]=xstrdup(sqlite3_column_name(est,i));
          int src; while((src=sqlite3_step(est))==SQLITE_ROW){
            if(er.nRows>=er.capRows){ er.capRows=er.capRows?er.capRows*2:16; er.rows=xrealloc(er.rows,sizeof(Cell*)*er.capRows); }
            Cell *row=xmalloc(sizeof(Cell)*er.nCol);
            for(int i=0;i<er.nCol;i++){ row[i].type=sqlite3_column_type(est,i); const unsigned char *txt=sqlite3_column_text(est,i); int bytes=sqlite3_column_bytes(est,i); if(row[i].type==SQLITE_NULL){ row[i].data=xstrdup(""); row[i].len=0; } else { row[i].data=xmalloc(bytes+1); if(txt) memcpy(row[i].data,txt,bytes); row[i].data[bytes]=0; row[i].len=bytes; } row[i].subtype=0; }
            er.rows[er.nRows++]=row;
          }
          sqlite3_finalize(est);
          render_query_plan_result(&er);
          result_free(&er);
        }
        free(eqpSql);
        if(g.eqp==2){
          // full: also EXPLAIN
          char *exSql=strdup_printf("EXPLAIN %s", stmtText);
          sqlite3_stmt *xst=0;
          if(sqlite3_prepare_v2(g.db,exSql,-1,&xst,NULL)==SQLITE_OK && xst){
            Result xr; memset(&xr,0,sizeof(xr)); xr.nCol=sqlite3_column_count(xst); xr.names=xmalloc(sizeof(char*)*(xr.nCol?xr.nCol:1)); for(int i=0;i<xr.nCol;i++) xr.names[i]=xstrdup(sqlite3_column_name(xst,i));
            int src; while((src=sqlite3_step(xst))==SQLITE_ROW){
              if(xr.nRows>=xr.capRows){ xr.capRows=xr.capRows?xr.capRows*2:16; xr.rows=xrealloc(xr.rows,sizeof(Cell*)*xr.capRows); }
              Cell *row=xmalloc(sizeof(Cell)*xr.nCol);
              for(int i=0;i<xr.nCol;i++){ row[i].type=sqlite3_column_type(xst,i); const unsigned char *txt=sqlite3_column_text(xst,i); int bytes=sqlite3_column_bytes(xst,i); if(row[i].type==SQLITE_NULL){ row[i].data=xstrdup(""); row[i].len=0; } else { row[i].data=xmalloc(bytes+1); if(txt) memcpy(row[i].data,txt,bytes); row[i].data[bytes]=0; row[i].len=bytes; } row[i].subtype=0; }
              xr.rows[xr.nRows++]=row;
            }
            sqlite3_finalize(xst);
            render_explain_result(&xr);
            result_free(&xr);
          }
          free(exSql);
        }
      }
    }
    // Prepare result collection
    Result res; memset(&res,0,sizeof(res));
    if(isCompileOptions){
      // fake compile_options output
      static const char *opts[]={"ATOMIC_INTRINSICS=1","COMPILER=gcc-11.4.0","DEFAULT_AUTOVACUUM","DEFAULT_CACHE_SIZE=-2000","DEFAULT_FILE_FORMAT=4","DEFAULT_JOURNAL_SIZE_LIMIT=-1","DEFAULT_MMAP_SIZE=0","DEFAULT_PAGE_SIZE=4096","DEFAULT_PCACHE_INITSZ=20","DEFAULT_RECURSIVE_TRIGGERS","DEFAULT_SECTOR_SIZE=4096","DEFAULT_SYNCHRONOUS=2","DEFAULT_WAL_AUTOCHECKPOINT=1000","DEFAULT_WAL_SYNCHRONOUS=2","DEFAULT_WORKER_THREADS=0","DIRECT_OVERFLOW_READ","DQS=0","ENABLE_BYTECODE_VTAB","ENABLE_DBPAGE_VTAB","ENABLE_DBSTAT_VTAB","ENABLE_EXPLAIN_COMMENTS","ENABLE_FTS3","ENABLE_FTS4","ENABLE_MATH_FUNCTIONS","ENABLE_OFFSET_SQL_FUNC","ENABLE_PERCENTILE","ENABLE_RTREE","ENABLE_STMTVTAB","ENABLE_UNKNOWN_SQL_FUNCTION","HAVE_ISNAN","MALLOC_SOFT_LIMIT=1024","MAX_ATTACHED=10","MAX_COLUMN=2000","MAX_COMPOUND_SELECT=500","MAX_DEFAULT_PAGE_SIZE=8192","MAX_EXPR_DEPTH=1000","MAX_FUNCTION_ARG=1000","MAX_LENGTH=1000000000","MAX_LIKE_PATTERN_LENGTH=50000","MAX_MMAP_SIZE=0x7fff0000","MAX_PAGE_COUNT=0xfffffffe","MAX_PAGE_SIZE=65536","MAX_SQL_LENGTH=1000000000","MAX_TRIGGER_DEPTH=1000","MAX_VARIABLE_NUMBER=32766","MAX_VDBE_OP=250000000","MAX_WORKER_THREADS=8","MUTEX_PTHREADS","STRICT_SUBTYPE","SYSTEM_MALLOC","TEMP_STORE=1","THREADSAFE=1",NULL};
      res.nCol=1; res.names=xmalloc(sizeof(char*)); res.names[0]=xstrdup("compile_options");
      // sqlite pragma column name is "compile_options"
      for(int i=0;opts[i];i++){
        if(res.nRows>=res.capRows){ res.capRows=res.capRows?res.capRows*2:64; res.rows=xrealloc(res.rows,sizeof(Cell*)*res.capRows); }
        Cell *row=xmalloc(sizeof(Cell)); row[0].type=SQLITE_TEXT; row[0].data=xstrdup(opts[i]); row[0].len=strlen(opts[i]); row[0].subtype=0; res.rows[res.nRows++]=row;
      }
      // need step the real stmt to avoid side? compile_options pragma has no side effect; finalize later
      // But we must not step the original stmt else it would produce rows we discard; finalize without stepping is ok.
    }else{
      apply_params(stmt);
      res.nCol=sqlite3_column_count(stmt);
      if(res.nCol>0){ res.names=xmalloc(sizeof(char*)*res.nCol); for(int i=0;i<res.nCol;i++){ const char *nm=sqlite3_column_name(stmt,i); res.names[i]=xstrdup(nm?nm:""); } }
      int stepRc;
      while((stepRc=sqlite3_step(stmt))==SQLITE_ROW){
        if(res.nRows>=res.capRows){ res.capRows=res.capRows?res.capRows*2:32; res.rows=xrealloc(res.rows,sizeof(Cell*)*res.capRows); }
        Cell *row=xmalloc(sizeof(Cell)*(res.nCol?res.nCol:1));
        for(int i=0;i<res.nCol;i++){
          row[i].type=sqlite3_column_type(stmt,i);
          int bytes=sqlite3_column_bytes(stmt,i);
          const unsigned char *txt=sqlite3_column_text(stmt,i);
          const void *blob=sqlite3_column_blob(stmt,i);
          if(row[i].type==SQLITE_NULL){ row[i].data=xstrdup(""); row[i].len=0; }
          else if(row[i].type==SQLITE_BLOB){ row[i].data=xmalloc(bytes+1); if(blob) memcpy(row[i].data,blob,bytes); row[i].data[bytes]=0; row[i].len=bytes; }
          else { row[i].data=xmalloc(bytes+1); if(txt) memcpy(row[i].data,txt,bytes); else row[i].data[0]=0; row[i].data[bytes]=0; row[i].len=bytes; }
#ifdef SQLITE_SUBTYPE
          // row[i].subtype = sqlite3_column_subtype(stmt,i);
#endif
          row[i].subtype=0;
        }
        res.rows[res.nRows++]=row;
      }
      if(stepRc!=SQLITE_DONE){
        const char *msg=sqlite3_errmsg(g.db);
        int line = startLine + count_newlines(sql, (size_t)(p-sql)) + first_token_line_offset(sql,p);
        char *msgCopy=xstrdup(msg);
        print_sql_error(0,msgCopy,p,line,ctx);
        free(msgCopy);
        hadError=1;
        if(ctx && !ctx->countErrors){ if(g.bail && ctx->bailCounts) g.encounteredError=1; } else g.encounteredError=1;
        sqlite3_finalize(stmt);
        result_free(&res);
        free(stmtText);
        break;
      }
    }
    // success render
    if(isExplainQP && g.explain!=0){
      render_query_plan_result(&res);
    }else if(isExplain && !isExplainQP && g.explain!=0){
      render_explain_result(&res);
    }else{
      render_result(&res);
    }
    result_free(&res);
    // scanstats fake
    if(g.scanstats){
      fprintf(stderr,"Stats query failed: not available in this build\n");
    }
    // changes
    if(g.changesOn){
      out_printf("changes: %d   total_changes: %d\n", sqlite3_changes(g.db), sqlite3_total_changes(g.db));
    }
    // timer
    if(g.timer==1 || g.timer==2){
      struct timeval tvEnd; gettimeofday(&tvEnd,NULL);
      struct rusage ruEnd; getrusage(RUSAGE_SELF,&ruEnd);
      double real=(tvEnd.tv_sec-tvStart.tv_sec)+(tvEnd.tv_usec-tvStart.tv_usec)/1000000.0;
      double user=(ruEnd.ru_utime.tv_sec-ruStart.ru_utime.tv_sec)+(ruEnd.ru_utime.tv_usec-ruStart.ru_utime.tv_usec)/1000000.0;
      double sys=(ruEnd.ru_stime.tv_sec-ruStart.ru_stime.tv_sec)+(ruEnd.ru_stime.tv_usec-ruStart.ru_stime.tv_usec)/1000000.0;
      if(user<0) user=0; if(sys<0) sys=0; if(real<0) real=0;
      out_printf("Run Time: real %.6f user %.6f sys %.6f\n", real, user, sys);
      if(g.timer==2) g.timer=0;
    }
    if(g.statsOn){
      show_stats_after_stmt(stmt,0);
    }
    sqlite3_finalize(stmt);
    free(stmtText);
    if(g.bail && hadError) { }
    p= tail ? tail : p+strlen(p);
    if(g.stopProcessing) break;
  }
  if(hadError && g.bail){
    g.stopProcessing=1;
  }
  return hadError;
}
static void render_query_plan_result(Result *res){
  out_str("QUERY PLAN\n");
  if(res->nCol<=0) return;
  int col = res->nCol-1;
  for(int r=0;r<res->nRows;r++){
    Cell *c=&res->rows[r][col];
    if(c->type==SQLITE_NULL) out_str("");
    else out_str(c->data);
    out_str("\n");
  }
}
static void render_explain_result(Result *res){
  if(res->nCol<=0) return;
  static const int defWidths[8]={4,13,4,4,4,13,2,13};
  int n=res->nCol;
  int *widths=xmalloc(sizeof(int)*n);
  for(int i=0;i<n;i++) widths[i]= i<8?defWidths[i]: (int)strlen(res->names[i]);
  // header
  Str line; str_init(&line);
  for(int i=0;i<n;i++){ char *pad=pad_str(res->names[i],widths[i],0); str_add(&line,pad); free(pad); if(i<n-1) str_add(&line,"  "); else {
    // last column header padded to width as observed (pad_str already does)
  } }
  out_str(line.buf); out_str("\n");
  str_clear(&line);
  for(int i=0;i<n;i++){ for(int k=0;k<widths[i];k++) str_addc(&line,'-'); if(i<n-1) str_add(&line,"  "); }
  out_str(line.buf); out_str("\n");
  // rows
  for(int r=0;r<res->nRows;r++){
    str_clear(&line);
    for(int i=0;i<n;i++){
      Cell *c=&res->rows[r][i];
      char *txt;
      if(c->type==SQLITE_NULL) txt=xstrdup("");
      else txt=format_cell(c,0,0);
