  else if(starts_ci(msg,"ambiguous column name:")) { colon=strchr(msg,':'); isColumn=1; }
  else if(starts_ci(msg,"no such function:")) { colon=strchr(msg,':'); isColumn=1; }
  else if(strstr(msg,"already exists")){
    // extract object name: words: type name already...
    // find CREATE ...name
    // tokenize residual: look for create then next non-keyword token
    // Simple: find object name by parsing msg: second word
    char *copy=xstrdup(msg);
