    }
    // changes
    if(g.changesOn){
      out_printf("changes: %d   total_changes: %d\n", sqlite3_changes(g.db), sqlite3_total_changes(g.db));
    }
    // timer
    if(g.timer==1 || g.timer==2){
      struct timeval tvEnd; gettimeofday(&tvEnd,NULL);
      struct rusage ruEnd; getrusage(RUSAGE_SELF,&ruEnd);
      double real=(tvEnd.tv_sec-tvStart.tv_sec)+(tvEnd.tv_usec-tvStart.tv_usec)/1000000.0;
      double user=(ruEnd.ru_utime.tv_sec-ruStart.ru_utime.tv_sec)+(ruEnd.ru_utime.tv_usec-ruStart.ru_utime.tv_usec)/1000000.0;
      double sys=(ruEnd.ru_stime.tv_sec-ruStart.ru_stime.tv_sec)+(ruEnd.ru_stime.tv_usec-ruStart.ru_stime.tv_usec)/1000000.0;
      if(user<0) user=0; if(sys<0) sys=0; if(real<0) real=0;
      out_printf("Run Time: real %.6f user %.6f sys %.6f\n", real, user, sys);
      if(g.timer==2) g.timer=0;
    }
    if(g.statsOn){
      show_stats_after_stmt(stmt,0);
    }
    sqlite3_finalize(stmt);
    free(stmtText);
    if(g.bail && hadError) { }
    p= tail ? tail : p+strlen(p);
    if(g.stopProcessing) break;
  }
  if(hadError && g.bail){
    g.stopProcessing=1;
  }
  return hadError;
}
static void render_query_plan_result(Result *res){
  out_str("QUERY PLAN\n");
  if(res->nCol<=0) return;
  int col = res->nCol-1;
  for(int r=0;r<res->nRows;r++){
    Cell *c=&res->rows[r][col];
    if(c->type==SQLITE_NULL) out_str("");
    else out_str(c->data);
    out_str("\n");
  }
}
static void render_explain_result(Result *res){
  if(res->nCol<=0) return;
  static const int defWidths[8]={4,13,4,4,4,13,2,13};
  int n=res->nCol;
  int *widths=xmalloc(sizeof(int)*n);
  for(int i=0;i<n;i++) widths[i]= i<8?defWidths[i]: (int)strlen(res->names[i]);
  // header
  Str line; str_init(&line);
  for(int i=0;i<n;i++){ char *pad=pad_str(res->names[i],widths[i],0); str_add(&line,pad); free(pad); if(i<n-1) str_add(&line,"  "); else {
    // last column header padded to width as observed (pad_str already does)
  } }
  out_str(line.buf); out_str("\n");
  str_clear(&line);
  for(int i=0;i<n;i++){ for(int k=0;k<widths[i];k++) str_addc(&line,'-'); if(i<n-1) str_add(&line,"  "); }
  out_str(line.buf); out_str("\n");
  // rows
  for(int r=0;r<res->nRows;r++){
    str_clear(&line);
    for(int i=0;i<n;i++){
      Cell *c=&res->rows[r][i];
      char *txt;
      if(c->type==SQLITE_NULL) txt=xstrdup("");
      else txt=format_cell(c,0,0);
      if(i<n-1){ char *pad=pad_str(txt,widths[i],0); str_add(&line,pad); free(pad); str_add(&line,"  "); }
      else str_add(&line,txt);
      free(txt);
    }
    out_str(line.buf); out_str("\n");
  }
  str_free(&line); free(widths);
}
static void show_stats_after_stmt(sqlite3_stmt *stmt,int isStmtStats){
