  sqlite3_db_status(g.db,SQLITE_DBSTATUS_CACHE_HIT,&iv,&ivHi,0); int cacheHit=iv;
  sqlite3_db_status(g.db,SQLITE_DBSTATUS_CACHE_MISS,&iv,&ivHi,0); int cacheMiss=iv;
