/* Tokenizer */
typedef struct { char **argv; int *offsets; int argc; int cap; } Tokens;
static void tokens_free(Tokens *t){ for(int i=0;i<t->argc;i++) free(t->argv[i]); free(t->argv); free(t->offsets); memset(t,0,sizeof(*t)); }
static void tokens_add(Tokens *t,char *tok,int off){ if(t->argc>=t->cap){ t->cap=t->cap?t->cap*2:16; t->argv=xrealloc(t->argv,sizeof(char*)*t->cap); t->offsets=xrealloc(t->offsets,sizeof(int)*t->cap); } t->argv[t->argc]=tok; t->offsets[t->argc]=off; t->argc++; }
static void tokenize_line(const char *line,Tokens *out){
  memset(out,0,sizeof(*out));
  const char *p=line;
  while(*p){
    while(*p==' '||*p=='\t'||*p=='\r'||*p=='\n') p++;
    if(!*p) break;
    int off=(int)(p-line);
    if(*p=='\'' || *p=='"'){
      char q=*p; p++;
      const char *start=p;
      while(*p && *p!=q) p++;
      char *tok=xstrndup(start,p-start);
      if(*p==q) p++;
      tokens_add(out,tok,off);
    }else{
      const char *start=p;
      while(*p && *p!=' ' && *p!='\t' && *p!='\r' && *p!='\n') p++;
      char *tok=xstrndup(start,p-start);
      tokens_add(out,tok,off);
    }
  }
}
