/* ---------- .mode implementation ---------- */
typedef struct TagEntry { char *name; ModeCfg cfg; } TagEntry;
static TagEntry *tags=0; static int nTags=0, capTags=0;
static void save_tag(const char *name){
  for(int i=0;i<nTags;i++) if(!strcmp(tags[i].name,name)){ modecfg_copy(&tags[i].cfg,&g.cfg); return; }
  if(nTags>=capTags){ capTags=capTags?capTags*2:8; tags=xrealloc(tags,sizeof(TagEntry)*capTags); }
  tags[nTags].name=xstrdup(name);
  memset(&tags[nTags].cfg,0,sizeof(ModeCfg));
  modecfg_copy(&tags[nTags].cfg,&g.cfg);
  nTags++;
}
static TagEntry *find_tag(const char *name){ for(int i=0;i<nTags;i++) if(!strcmp(tags[i].name,name)) return &tags[i]; return 0; }
static const char *quote_display_name(int q){
  switch(q){ case Q_OFF: return "off"; case Q_SQL: return "sql"; case Q_RELAXED: return "relaxed"; case Q_CSV: return "hex"; case Q_HTML: return "csv"; case Q_TCL: return "tcl"; case Q_JSON: return "json"; }
  return "off";
}
static const char *blob_display_name(int b){
  switch(b){ case BQ_AUTO: return "auto"; case BQ_TEXT: return "text"; case BQ_SQL: return "sql"; case BQ_HEX: return "hex"; case BQ_TCL: return "tcl"; case BQ_JSON: return "json"; case BQ_SIZE: return "size"; }
  return "auto";
}
static const char *escape_display_name(int e){
  switch(e){ case ESC_AUTO: return "auto"; case ESC_OFF: return "off"; case ESC_ASCII: return "ascii"; case ESC_SYMBOL: return "symbol"; }
  return "auto";
}
static const char *title_display_name(void){
  ModeCfg *c=&g.cfg;
  if(!c->showHeader) return "off";
  switch(c->titleEnc){ case TITLE_ON: return "on"; case TITLE_SQL: return "sql"; case TITLE_CSV: return "csv"; case TITLE_HTML: return "html"; case TITLE_TCL: return "tcl"; case TITLE_JSON: return "json"; case TITLE_PLAIN: return "plain"; }
  return "on";
}
static int mode_uses_titles(int mode){
  return !(mode==M_JSON||mode==M_JOBJECT||mode==M_LINE||mode==M_COUNT||mode==M_OFF);
}
static char *mode_display_string(int verbose){
  ModeCfg *c=&g.cfg;
  Str s; str_init(&s);
  str_addf(&s,".mode %s",mode_name(c->mode));
  Preset preset=preset_for(c->mode);
  if(verbose){
    { char *q=display_quote(c->align); str_addf(&s," --align %s",q); free(q); }
    str_addf(&s," --border %s",c->border?"on":"off");
    str_addf(&s," --blob-quote %s",blob_display_name(c->blobQuote));
    { char *q=display_quote(c->colSep); str_addf(&s," --colsep %s",q); free(q); }
    str_addf(&s," --escape %s",escape_display_name(c->escape));
    if(c->lineLimit==0 && c->charLimit==0 && c->titleLimit==0) str_add(&s," --limits off");
    else if(c->lineLimit==5 && c->charLimit==300 && c->titleLimit==20) str_add(&s," --limits on");
    else str_addf(&s," --limits %d,%d,%d",c->lineLimit,c->charLimit,c->titleLimit);
    str_addf(&s," --multiinsert %d",c->multiInsert);
    { char *q=display_quote(c->nullVal); str_addf(&s," --null %s",q); free(q); }
    str_addf(&s," --quote %s",quote_display_name(c->quote));
    { char *q=display_quote(c->rowSep); str_addf(&s," --rowsep %s",q); free(q); }
    if(c->screenWidthAuto) str_add(&s," --sw auto"); else str_addf(&s," --sw %d",c->screenWidth);
    { char *q=display_quote(c->tablename?c->tablename:""); str_addf(&s," --tablename %s",q); free(q); }
    str_addf(&s," --textjsonb %s",c->textJsonb?"on":"off");
    if(mode_uses_titles(c->mode)){
      str_addf(&s," --titles %s",title_display_name());
    }
    if(c->nWidths==0) str_add(&s," --widths \"\"");
    else { str_add(&s," --widths "); for(int i=0;i<c->nWidths;i++){ if(i) str_addc(&s,','); str_addf(&s,"%d",c->widths[i]); } }
    str_addf(&s," --wordwrap %s",c->wordWrap?"on":"off");
    if(c->wrap) str_addf(&s," --wrap %d",c->wrap);
    return s.buf;
  }
  /* normal */
  int isColumnar = (c->mode==M_COLUMN||c->mode==M_BOX||c->mode==M_TABLE||c->mode==M_MARKDOWN||c->mode==M_QBOX||c->mode==M_PSQL||c->mode==M_SPLIT);
  int isDelimited = (c->mode==M_LIST||c->mode==M_CSV||c->mode==M_QUOTE||c->mode==M_C||c->mode==M_JATOM||c->mode==M_TCL||c->mode==M_TABS||c->mode==M_ASCII);
  // align
  if(isColumnar && c->align && c->align[0]){ char *q=display_quote(c->align); str_addf(&s," --align %s",q); free(q); }
  // blob-quote: special c/tcl always if not auto, others if differs from preset
  if(c->blobQuote!=BQ_AUTO){
    if(c->mode==M_C || c->mode==M_TCL || c->blobQuote!=preset.blobQuote) str_addf(&s," --blob-quote %s",blob_display_name(c->blobQuote));
  }
  // border
  if(!c->border && (c->mode==M_BOX||c->mode==M_QBOX||c->mode==M_TABLE)) str_add(&s," --border off");
  // colsep: only delimited / line
  if((isDelimited || c->mode==M_LINE) && strcmp(c->colSep,preset.colSep)!=0){ char *q=display_quote(c->colSep); str_addf(&s," --colsep %s",q); free(q); }
  // escape
  if(c->escape!=ESC_AUTO) str_addf(&s," --escape %s",escape_display_name(c->escape));
  // limits
  if(c->lineLimit||c->charLimit||c->titleLimit){
    if(c->lineLimit==5 && c->charLimit==300 && c->titleLimit==20) str_add(&s," --limits on");
    else str_addf(&s," --limits %d,%d,%d",c->lineLimit,c->charLimit,c->titleLimit);
  }
  // null
  if(strcmp(c->nullVal,preset.nullVal)!=0){ char *q=display_quote(c->nullVal); str_addf(&s," --null %s",q); free(q); }
  // quote
  if(c->quote!=preset.quote) str_addf(&s," --quote %s",quote_display_name(c->quote));
  // rowsep
  if((isDelimited || c->mode==M_LINE) && strcmp(c->rowSep,preset.rowSep)!=0){ char *q=display_quote(c->rowSep); str_addf(&s," --rowsep %s",q); free(q); }
  // sw
  if(c->mode==M_SPLIT && c->screenWidthAuto) str_add(&s," --sw auto");
  else if(isColumnar && (c->screenWidthAuto || c->screenWidth!=0)){
    if(c->screenWidthAuto) str_add(&s," --sw auto"); else str_addf(&s," --sw %d",c->screenWidth);
  }
  // tablename: insert always
  if(c->mode==M_INSERT){ char *q=display_quote(c->tablename?c->tablename:""); str_addf(&s," --tablename %s",q); free(q); }
  // textjsonb
  if(c->textJsonb) str_add(&s," --textjsonb on");
  // titles
  if(mode_uses_titles(c->mode)){
    int presetHeaders = preset.headers;
    if(c->titleEnc!=TITLE_ON){
      str_addf(&s," --titles %s",title_display_name());
    }else if(c->showHeader!=presetHeaders){
      str_addf(&s," --titles %s",c->showHeader?"on":"off");
    }
  }
  // widths
  if(isColumnar && c->nWidths>0){
    str_add(&s," --widths "); for(int i=0;i<c->nWidths;i++){ if(i) str_addc(&s,','); str_addf(&s,"%d",c->widths[i]); }
  }
  // wordwrap as --ww
  if(isColumnar && c->wordWrap) str_add(&s," --ww");
  return s.buf;
}
static int mode_error(SrcCtx *ctx,const char *line,int off,const char *msg,const char *extra){
  dot_error_caret(ctx,line,off,msg,extra);
  return 1;
}
/* apply mode preset with separator logic - redefined earlier? We already have apply_mode_preset, but adjust colsep handling */
C_EOF
"}

