/* ---------- other dot commands ---------- */
static int like_match(const char *pattern,const char *str); // sql LIKE matcher simple
static int glob_match_str(const char *pat,const char *str);
static int run_sql_collect(const char *sql,Result *res,int *errOut); /* helper defined below */
static void free_result_helper(Result *r){ result_free(r); }

/* LIKE matching: % _, escape? case-insensitive for ASCII as sqlite LIKE */
static int like_match_rec(const char *p,const char *s){
  if(!*p) return *s==0;
  if(*p=='%'){ while(p[1]=='%') p++; if(!p[1]) return 1; for(const char *t=s;;t++){ if(like_match_rec(p+1,t)) return 1; if(!*t) break; } return 0; }
  if(!*s) return 0;
  if(*p=='_') return like_match_rec(p+1,s+1);
  if(tolower((unsigned char)*p)!=tolower((unsigned char)*s)) return 0;
  return like_match_rec(p+1,s+1);
}
static int like_match(const char *pattern,const char *str){ return like_match_rec(pattern,str); }
static int glob_match_str(const char *pat,const char *str){
  // simple glob * ? []
  if(!*pat) return *str==0;
  if(*pat=='*'){ while(pat[1]=='*') pat++; if(!pat[1]) return 1; for(const char *t=str;;t++){ if(glob_match_str(pat+1,t)) return 1; if(!*t) break; } return 0; }
  if(!*str) return 0;
  if(*pat=='?') return glob_match_str(pat+1,str+1);
  if(*pat=='['){
    const char *p=pat+1; int neg=0; if(*p=='^'){neg=1;p++;}
    int matched=0; int first=1;
    while(*p && (*p!=']' || first)){ first=0; if(p[1]=='-' && p[2] && p[2]!=']'){ if(*str>=p[0] && *str<=p[2]) matched=1; p+=3; } else { if(*str==*p) matched=1; p++; } }
    if(!*p) return *pat==*str && glob_match_str(pat+1,str+1);
    if(matched==neg) return 0;
    return glob_match_str(p+1,str+1);
  }
  if(*pat!=*str) return 0;
  return glob_match_str(pat+1,str+1);
}
/* collect rows from a SQL query using current db, no output */
static int run_sql_collect(const char *sql,Result *res,int *errOut){
  memset(res,0,sizeof(*res));
  if(errOut) *errOut=0;
  sqlite3_stmt *stmt=0;
  int rc=sqlite3_prepare_v2(g.db,sql,-1,&stmt,NULL);
  if(rc!=SQLITE_OK){ if(errOut) *errOut=1; return 1; }
  res->nCol=sqlite3_column_count(stmt);
  if(res->nCol>0){ res->names=xmalloc(sizeof(char*)*res->nCol); for(int i=0;i<res->nCol;i++) res->names[i]=xstrdup(sqlite3_column_name(stmt,i)); }
  int src;
  while((src=sqlite3_step(stmt))==SQLITE_ROW){
    if(res->nRows>=res->capRows){ res->capRows=res->capRows?res->capRows*2:32; res->rows=xrealloc(res->rows,sizeof(Cell*)*res->capRows); }
    Cell *row=xmalloc(sizeof(Cell)*(res->nCol?res->nCol:1));
    for(int i=0;i<res->nCol;i++){ row[i].type=sqlite3_column_type(stmt,i); int bytes=sqlite3_column_bytes(stmt,i); const unsigned char *txt=sqlite3_column_text(stmt,i); const void *blob=sqlite3_column_blob(stmt,i); if(row[i].type==SQLITE_NULL){ row[i].data=xstrdup(""); row[i].len=0; } else if(row[i].type==SQLITE_BLOB){ row[i].data=xmalloc(bytes+1); if(blob) memcpy(row[i].data,blob,bytes); row[i].data[bytes]=0; row[i].len=bytes; } else { row[i].data=xmalloc(bytes+1); if(txt) memcpy(row[i].data,txt,bytes); row[i].data[bytes]=0; row[i].len=bytes; } row[i].subtype=0; }
    res->rows[res->nRows++]=row;
  }
  sqlite3_finalize(stmt);
  if(src!=SQLITE_DONE){ if(errOut) *errOut=1; return 1; }
  return 0;
}
static int exec_sql_silent(const char *sql){
  char *err=0; int rc=sqlite3_exec(g.db,sql,NULL,NULL,&err); if(err) sqlite3_free(err); return rc!=SQLITE_OK;
}
/* formatting names list like .tables: columns aligned */
static void print_names_list(char **names,int n){
