  }
  const char *fileArg=tok->argv[idx++];
  if(idx>=tok->argc){
    char *pre=dot_err_prefix(ctx); fprintf(stderr,"%sMissing TABLE argument\n\n",pre); free(pre); return 1;
  }
  const char *tableArg=tok->argv[idx++];
  if(idx<tok->argc){
    // extra arguments? Original might treat as ... ignore?
  }
  // Determine separators and csv mode
  int isTabsMode = (g.cfg.mode==M_TABS);
  int isAsciiMode = (g.cfg.mode==M_ASCII);
  char sep = hasColSep? colSepOpt : (g.cfg.colSep && g.cfg.colSep[0]? g.cfg.colSep[0]:'|');
  char rowSep = hasRowSep? rowSepOpt : (g.cfg.rowSep && g.cfg.rowSep[0]? g.cfg.rowSep[0]:'\n');
  int useCsv=1;
  if(asciiMode){ sep=hasColSep?colSepOpt:'\037'; rowSep=hasRowSep?rowSepOpt:'\036'; useCsv=0; }
