  if(fileArg[0]=='|'){
    fp=popen(fileArg+1,"r"); if(!fp){ char *pre=dot_err_prefix(ctx); (void)pre; fprintf(stderr,"Error: cannot open \"%s\"\n",fileArg); return 1; } isPipe=1; in.fp=fp;
  }else if(fileArg[0]=='<' && fileArg[1]=='<'){
    isHeredoc=1;
    const char *label=fileArg+2;
    // Read lines from current input reader (reader->in) until line == label
    // reader parameter is current input; we need getline from it
    if(reader && reader->in){
      char *line=0; size_t cap=0; ssize_t n;
      while((n=getline(&line,&cap,reader->in))>=0){
        reader->lineno++; if(ctx) ctx->lineno=reader->lineno;
        // line without newline for comparison
        char *copy=xstrdup(line); size_t L=strlen(copy); while(L && (copy[L-1]=='\n'||copy[L-1]=='\r')) copy[--L]=0;
        if(!strcmp(copy,label)){ free(copy); break; }
        free(copy);
        str_add(&heredocData,line);
      }
      free(line);
    }
    in.mem=heredocData.buf; in.memLen=heredocData.len; in.memPos=0;
  }else{
    fp=fopen(fileArg,"rb");
    if(!fp){ char *pre=dot_err_prefix(ctx); fprintf(stderr,"%scannot open \"%s\"\n",pre,fileArg); free(pre); return 1; }
    in.fp=fp;
  }
