    if(dot) tblName=dot+1;
    char *sql=strdup_printf("SELECT count(*) FROM sqlite_schema WHERE name=%s", sql_quote_text_internal(tblName,strlen(tblName),0));
    // Instead use collect
    Result r; int e=0;
    // build using quote
    char *qn=sql_quote_text_internal(tblName,strlen(tblName),0);
    char *sql2=strdup_printf("SELECT sql FROM sqlite_schema WHERE type IN ('table','view') AND name=%s",qn); free(qn);
    run_sql_collect(sql2,&r,&e); free(sql2); free(sql);
    if(r.nRows>0) tableExists=1;
    result_free(&r);
    if(tableExists){
      char *qid=quote_ident(tblName);
      char *pragmaSql=0;
      if(schemaOpt) pragmaSql=strdup_printf("PRAGMA %s.table_info(%s)",schemaOpt,qid);
      else if(dot){ char *schemaPart=xstrndup(tableArg,dot-tableArg); pragmaSql=strdup_printf("PRAGMA %s.table_info(%s)",schemaPart,qid); free(schemaPart); }
      else pragmaSql=strdup_printf("PRAGMA table_info(%s)",qid);
      Result pr; int ee=0; run_sql_collect(pragmaSql,&pr,&ee); free(pragmaSql); free(qid);
      nColTable=pr.nRows;
      result_free(&pr);
    }
  }
