        else { char *qt=quote_ident(tableArg); str_add(&sql,qt); free(qt); }
      }
      str_addc(&sql,'(');
      for(int i=0;i<cnt;i++){
        if(i) str_addc(&sql,',');
        char *qid=quote_ident(fields[i]); str_add(&sql,qid); free(qid); str_add(&sql," ANY");
      }
      str_addc(&sql,')');
      char *errmsg=0; int rc=sqlite3_exec(g.db,sql.buf,NULL,NULL,&errmsg);
      str_free(&sql);
      if(rc!=SQLITE_OK){ fprintf(stderr,"%s\n",errmsg?errmsg:"error"); if(errmsg) sqlite3_free(errmsg); hadErr=1; for(int i=0;i<cnt;i++) free(fields[i]); free(fields); break; }
      nColTable=cnt;
      // prepare insert
      firstRow=0;
      // continue to next row (header not inserted)
      for(int i=0;i<cnt;i++) free(fields[i]); free(fields);
      // create insert stmt below lazily for data rows
      continue;
    }
    firstRow=0;
    if(!insertStmt){
      // build insert: INSERT INTO table VALUES(?,?,..)
      Str sql; str_init(&sql); str_add(&sql,"INSERT INTO ");
      {
        // tableArg quoting: if contains dot, quote each part
        const char *dot=strrchr(tableArg,'.');
        if(schemaOpt){ char *qs=quote_ident(schemaOpt); str_add(&sql,qs); free(qs); str_addc(&sql,'.'); char *qt=quote_ident(tableArg); /* if tableArg has dot, only tail */ if(dot) { free(qt); qt=quote_ident(dot+1); } str_add(&sql,qt); free(qt); }
        else if(dot){ char *schem=xstrndup(tableArg,dot-tableArg); char *qs=quote_ident(schem); str_add(&sql,qs); free(qs); free(schem); str_addc(&sql,'.'); char *qt=quote_ident(dot+1); str_add(&sql,qt); free(qt); }
        else { char *qt=quote_ident(tableArg); str_add(&sql,qt); free(qt); }
      }
      str_add(&sql," VALUES(");
      for(int i=0;i<nColTable;i++){ if(i) str_addc(&sql,','); str_addc(&sql,'?'); }
      str_addc(&sql,')');
      int rc=sqlite3_prepare_v2(g.db,sql.buf,-1,&insertStmt,NULL);
      str_free(&sql);
      if(rc!=SQLITE_OK){ fprintf(stderr,"%s\n",sqlite3_errmsg(g.db)); hadErr=1; for(int i=0;i<cnt;i++) free(fields[i]); free(fields); break; }
    }
