      fprintf(stderr,"%s:%d: expected %d columns but found %d - %s\n",dispName,lineNo,nColTable,cnt, cnt<nColTable?"filling the rest with NULL":"ignoring extra");
      // Original message for too many? It says? For filling it says "... - filling the rest with NULL". For extra, maybe "ignoring extra" conjectured; will probe later.
    }
    sqlite3_reset(insertStmt); sqlite3_clear_bindings(insertStmt);
    for(int i=0;i<nColTable;i++){
      if(i<cnt) sqlite3_bind_text(insertStmt,i+1,fields[i],-1,SQLITE_TRANSIENT);
