    if(rc!=SQLITE_DONE){
      fprintf(stderr,"%s:%d: INSERT failed: %s\n",fileArg,lineNo,sqlite3_errmsg(g.db));
      // original format? probe later
      hadErr=1;
    }
    if(verbose){ /* print? */ }
    for(int i=0;i<cnt;i++) free(fields[i]); free(fields);
  }
  if(insertStmt) sqlite3_finalize(insertStmt);
