  g.mainPrompt=xstrdup("SQLite /f> ");
  g.contPrompt=xstrdup("/B.../H> ");
  str_init(&g.memOut);
  str_init(&g.testcaseBuf);
  // register prompt test function later when db opened (register_functions needs patch to include it)
  int outputIsTty = isatty(fileno(stdout)) && isatty(fileno(stdin));
  if(outputIsTty){
    // tty initial mode
    apply_mode_preset(M_QBOX,M_QBOX);
    g.cfg.lineLimit=5; g.cfg.charLimit=300; g.cfg.titleLimit=20;
    g.cfg.quote=Q_RELAXED;
    g.cfg.screenWidthAuto=1; g.cfg.screenWidth=0;
    g.cfg.textJsonb=1;
    g.cfg.showHeader=1;
    free(g.cfg.colSep); g.cfg.colSep=xstrdup("");
    free(g.cfg.rowSep); g.cfg.rowSep=xstrdup("");
  }
  // argument collections
  char *dbArg=0; int dbArgIndex=0;
  typedef struct { char *str; int idx; } ArgItem;
  ArgItem *sqlArgs=0; int nSql=0, capSql=0;
  ArgItem *cmdArgs=0; int nCmd=0, capCmd=0;
  char *initFile=0;
  int noInit=0;
  int archiveFlag=0;
  char **archiveArgs=0; int nArch=0;
  int stopOptions=0;
  long maxSize=0; (void)maxSize;
  // temp options that need two args etc are processed during scan
  for(int i=1;i<argc;i++){
    char *arg=argv[i];
    if(archiveFlag){
      // shouldn't happen because -A breaks loop, but keep
      break;
    }
    if(!stopOptions && arg[0]=='-' && arg[1]!='\0'){
      if(!strcmp(arg,"--")){ stopOptions=1; continue; }
      const char *opt = (arg[1]=='-' ? arg+2 : arg+1);
      // helper to get next arg or error
      // We will handle each
      if(!strcmp(opt,"help")){
        fprintf(stderr,usageText,argv[0]); return 0;
      }
      if(!strcmp(opt,"version")){
        printf("%s\n",FAKE_VERSION_FULL); return 0;
      }
      if(!strcmp(opt,"A")){
        archiveFlag=1;
        // collect remaining args
        nArch=argc-(i+1);
        archiveArgs= argc>i+1 ? &argv[i+1] : 0;
        break;
      }
      // options with arguments (two-arg first)
      if(!strcmp(opt,"lookaside")||!strcmp(opt,"pagecache")){
        if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to %s\n",argv[0],arg); return 1; }
        char *first=argv[++i];
        if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to %s\n",argv[0],first); return 1; }
        char *second=argv[++i]; (void)second;
        // sqlite config ignore
        continue;
      }
      if(!strcmp(opt,"cmd")||!strcmp(opt,"init")||!strcmp(opt,"mmap")||!strcmp(opt,"newline")||!strcmp(opt,"nonce")||!strcmp(opt,"nullvalue")||!strcmp(opt,"screenwidth")||!strcmp(opt,"separator")||!strcmp(opt,"vfs")){
        if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to %s\n",argv[0],arg); return 1; }
        char *val=argv[++i]; int valIdx=i;
        if(!strcmp(opt,"cmd")){
          if(nCmd>=capCmd){ capCmd=capCmd?capCmd*2:8; cmdArgs=xrealloc(cmdArgs,sizeof(ArgItem)*capCmd); }
          cmdArgs[nCmd].str=val; cmdArgs[nCmd].idx=valIdx; nCmd++;
        }else if(!strcmp(opt,"init")){
          initFile=val;
        }else if(!strcmp(opt,"mmap")){ g.hasMmap=1; g.mmapSize=strtol(val,NULL,10); }
        else if(!strcmp(opt,"newline")){ free(g.cfg.rowSep); g.cfg.rowSep=xstrdup(val); }
        else if(!strcmp(opt,"nonce")){ free(g.nonce); g.nonce=xstrdup(val); }
        else if(!strcmp(opt,"nullvalue")){ free(g.cfg.nullVal); g.cfg.nullVal=xstrdup(val); }
        else if(!strcmp(opt,"screenwidth")){ g.cfg.screenWidth=atoi(val); g.cfg.screenWidthAuto=0; }
        else if(!strcmp(opt,"separator")){ free(g.cfg.colSep); g.cfg.colSep=xstrdup(val); }
        else if(!strcmp(opt,"vfs")){ free(g.vfsName); g.vfsName=xstrdup(val); }
        continue;
      }
      if(!strcmp(opt,"escape")||!strcmp(opt,"maxsize")){
        // special missing handling: if no next arg, unknown option
        if(i+1>=argc){
          const char *norm = (arg[1]=='-'? arg+1: arg);
          fprintf(stderr,"%s: Error: unknown option: %s\nUse -help for a list of options.\n",argv[0],norm); return 1;
        }
        char *val=argv[++i];
        if(!strcmp(opt,"escape")){
          if(!strcmp(val,"auto")) g.cfg.escape=ESC_AUTO;
          else if(!strcmp(val,"off")) g.cfg.escape=ESC_OFF;
          else if(!strcmp(val,"ascii")) g.cfg.escape=ESC_ASCII;
          else if(!strcmp(val,"symbol")) g.cfg.escape=ESC_SYMBOL;
          else { fprintf(stderr,"unknown control character escape mode \"%s\" - choices: auto off ascii symbol\n",val); return 1; }
        }else{
          maxSize=strtol(val,NULL,10);
        }
        continue;
      }
      // boolean / mode options
      if(!strcmp(opt,"append")){ g.appendFlag=1; continue; }
      if(!strcmp(opt,"bail")){ g.bail=1; continue; }
      if(!strcmp(opt,"batch")){ g.forceBatch=1; continue; }
      if(!strcmp(opt,"interactive")){ g.forceInteractive=1; continue; }
      if(!strcmp(opt,"echo")){ g.echo=1; continue; }
      if(!strcmp(opt,"header")){ g.cfg.showHeader=1; continue; }
      if(!strcmp(opt,"noheader")){ g.cfg.showHeader=0; continue; }
      if(!strcmp(opt,"ifexists")){ g.ifExistsFlag=1; continue; }
      if(!strcmp(opt,"readonly")){ g.readOnlyFlag=1; continue; }
      if(!strcmp(opt,"deserialize")){ g.deserializeFlag=1; continue; }
      if(!strcmp(opt,"zip")){ g.zipFlag=1; continue; }
      if(!strcmp(opt,"nofollow")){ g.noFollowFlag=1; continue; }
      if(!strcmp(opt,"noinit")){ noInit=1; continue; }
      if(!strcmp(opt,"safe")){ g.safeMode=1; continue; }
      if(!strcmp(opt,"unsafe-testing")){ /* enable test functions */ continue; }
      if(!strcmp(opt,"stats")){ g.statsOn=1; continue; }
      if(!strcmp(opt,"memtrace")||!strcmp(opt,"pcachetrace")||!strcmp(opt,"vfstrace")||!strcmp(opt,"no-rowid-in-view")){ continue; }
      // mode switches
      {
        int resolved=1; int m=-1;
        if(!strcmp(opt,"ascii")) m=M_ASCII;
        else if(!strcmp(opt,"box")) m=M_BOX;
        else if(!strcmp(opt,"column")) m=M_COLUMN;
        else if(!strcmp(opt,"csv")) m=M_CSV;
        else if(!strcmp(opt,"html")) m=M_HTML;
        else if(!strcmp(opt,"json")) m=M_JSON;
        else if(!strcmp(opt,"line")) m=M_LINE;
        else if(!strcmp(opt,"list")) m=M_LIST;
        else if(!strcmp(opt,"markdown")) m=M_MARKDOWN;
        else if(!strcmp(opt,"quote")) m=M_QUOTE;
        else if(!strcmp(opt,"table")) m=M_TABLE;
        else if(!strcmp(opt,"tabs")) m=M_TABS;
        if(m>=0){ apply_mode_preset(m,resolved); continue; }
      }
      // unknown
      {
        const char *norm = (arg[1]=='-'? arg+1: arg);
        fprintf(stderr,"%s: Error: unknown option: %s\nUse -help for a list of options.\n",argv[0],norm); return 1;
      }
    }else{
      // non-option
      if(!stopOptions && !strcmp(arg,"-")){ continue; }
      if(!dbArg){ dbArg=arg; dbArgIndex=i; }
      else {
        if(nSql>=capSql){ capSql=capSql?capSql*2:8; sqlArgs=xrealloc(sqlArgs,sizeof(ArgItem)*capSql); }
        sqlArgs[nSql].str=arg; sqlArgs[nSql].idx=i; nSql++;
      }
    }
  }
  // interactive determination
  if(g.forceBatch) g.isInteractive=0;
  else if(g.forceInteractive) g.isInteractive=1;
  else g.isInteractive = isatty(fileno(stdin))?1:0;
  // VFS check
  if(g.vfsName){
    if(!sqlite3_vfs_find(g.vfsName)){
      fprintf(stderr,"no such VFS: \"%s\"\n",g.vfsName); return 1;
    }
  }
  // script detection and DB filename
  char *scriptFile=0;
  char *dbFilename=dbArg?dbArg:":memory:";
  if(dbArg){
    // check existence and extension
    struct stat st;
    if(stat(dbArg,&st)==0 && S_ISREG(st.st_mode) && st.st_size>0){
      const char *ext=strrchr(dbArg,'.');
      if(ext && (equals_ci(ext,".sql")||equals_ci(ext,".txt"))){
        // check if it's a valid DB header and size >=100
        int isDb=0;
        FILE *fp=fopen(dbArg,"rb");
        if(fp){
          unsigned char hdr[16]; size_t rd=fread(hdr,1,16,fp); fclose(fp);
          if(rd>=16 && memcmp(hdr,"SQLite format 3",15)==0 && hdr[15]==0 && st.st_size>=100) isDb=1;
        }
        if(!isDb){
          scriptFile=dbArg;
          if(nSql>0){
            dbFilename=sqlArgs[0].str;
            // shift sqlArgs by 1
            // keep original indexes for remaining
            memmove(&sqlArgs[0],&sqlArgs[1],sizeof(ArgItem)*(nSql-1));
            nSql--;
          }else{
            dbFilename=":memory:";
          }
        }
      }
    }
  }
  // open DB
  if(open_db(dbFilename)!=0){
    // open_db already printed error for some cases; if db is still null and error was not printed (e.g. file is not db etc) it kept db open. If g.db is null, we fail
    if(!g.db) return 1;
  }
  if(archiveFlag){
    // run .archive with archiveArgs and exit 0
    Tokens tok; memset(&tok,0,sizeof(tok));
    tokens_add(&tok,xstrdup("archive"),0);
    for(int i=0;i<nArch;i++){
      tokens_add(&tok,xstrdup(archiveArgs[i]),0);
    }
    SrcCtx actx; memset(&actx,0,sizeof(actx)); actx.kind=3; actx.countErrors=0;
    // archive command via do_archive_command directly; its return ignored
    do_archive_command(&tok,&actx);
    tokens_free(&tok);
    if(g.db) sqlite3_close(g.db);
    return 0;
  }
  // init / rc file
  if(!g.stopProcessing){
    if(initFile){
      FILE *fp=fopen(initFile,"r");
      if(!fp){
        fprintf(stderr,"cannot open: \"%s\"\n",initFile);
      }else{
        SrcCtx ictx; memset(&ictx,0,sizeof(ictx)); ictx.kind=1; ictx.filename=xstrdup(initFile); ictx.countErrors=0; ictx.bailCounts=1;
        InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=fp; reader.ctx=&ictx; reader.isPrimary=1; str_init(&reader.sqlBuf);
        process_input(&reader);
        str_free(&reader.sqlBuf); free(ictx.filename); fclose(fp);
      }
    }else if(!noInit && isatty(fileno(stdin))){
      const char *home=getenv("HOME");
      if(home){
        char *rcpath=strdup_printf("%s/.sqliterc",home);
        FILE *fp=fopen(rcpath,"r");
        if(fp){
          SrcCtx ictx; memset(&ictx,0,sizeof(ictx)); ictx.kind=1; ictx.filename=xstrdup(rcpath); ictx.countErrors=0; ictx.bailCounts=1;
          InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=fp; reader.ctx=&ictx; reader.isPrimary=1; str_init(&reader.sqlBuf);
          process_input(&reader);
          str_free(&reader.sqlBuf); free(ictx.filename); fclose(fp);
        }
        free(rcpath);
      }
    }
  }
  // -cmd commands
  for(int i=0;i<nCmd && !g.stopProcessing;i++){
    SrcCtx cctx; memset(&cctx,0,sizeof(cctx)); cctx.kind=3; cctx.argIndex=cmdArgs[i].idx; cctx.countErrors=0; cctx.bailCounts=1;
    nonceActiveCurrent=noncePending; noncePending=0;
    // echo for -cmd? No echo of cmd string itself (original). But if -cmd is a dot/SQL and echo is on, its execution internally does not echo (process_command_string does not echo)
    process_command_string(cmdArgs[i].str,&cctx);
    nonceActiveCurrent=0;
  }
  // script file
  if(scriptFile && !g.stopProcessing){
    FILE *fp=fopen(scriptFile,"r");
    if(fp){
      SrcCtx sctx; memset(&sctx,0,sizeof(sctx)); sctx.kind=1; sctx.filename=xstrdup(scriptFile); sctx.countErrors=0; sctx.bailCounts=0;
      InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=fp; reader.ctx=&sctx; reader.isPrimary=1; str_init(&reader.sqlBuf);
      process_input(&reader);
      str_free(&reader.sqlBuf); free(sctx.filename); fclose(fp);
    }
  }
  int processedMainInput=0;
  if(!g.stopProcessing && nSql>0){
    processedMainInput=1;
    for(int i=0;i<nSql;i++){
      if(g.stopProcessing) break;
      SrcCtx sctx; memset(&sctx,0,sizeof(sctx)); sctx.kind=2; sctx.argIndex=sqlArgs[i].idx; sctx.countErrors=1; sctx.bailCounts=1;
      if(g.echo){ out_str(sqlArgs[i].str); if(sqlArgs[i].str[0] && sqlArgs[i].str[strlen(sqlArgs[i].str)-1]!='\n') out_str("\n"); out_flush(); }
      nonceActiveCurrent=noncePending; noncePending=0;
      int rc=process_command_string(sqlArgs[i].str,&sctx);
      nonceActiveCurrent=0;
      if(rc!=0){
        // stop further SQL args
        break;
      }
      // exec_sql_chunk for SQL args returns hadError via rc; for dot commands process_command_string returns rc
      // Also if an error occurred inside chunk but rc... exec returns hadError, process_command_string for SQL returns that.
    }
  }
  if(!g.stopProcessing && nSql==0 && !scriptFile){
    // banner if interactive
    if(g.isInteractive){
      printf("SQLite version " FAKE_VERSION " " FAKE_SOURCE_ID "\n");
      printf("Enter \".help\" for usage hints.\n");
      fflush(stdout);
    }
    SrcCtx ictx; memset(&ictx,0,sizeof(ictx)); ictx.kind=0; ictx.countErrors=1; ictx.bailCounts=1;
    InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=stdin; reader.ctx=&ictx; reader.isPrimary=1; str_init(&reader.sqlBuf);
    process_input(&reader);
    str_free(&reader.sqlBuf);
    processedMainInput=1;
  }
  (void)processedMainInput; (void)dbArgIndex;
  out_flush();
  if(g.db) sqlite3_close(g.db);
  if(testRuns>0){
    printf("%d test%s run with %d error%s\n",testRuns, testRuns==1?"":"s", testErrors, testErrors==1?"":"s");
    fflush(stdout);
  }
  if(exitRequested) return g.exitCode;
  if(g.encounteredError) return 1;
  return 0;
}
C_EOF
"}

