        else if(!strcmp(opt,"html")) m=M_HTML;
        else if(!strcmp(opt,"json")) m=M_JSON;
        else if(!strcmp(opt,"line")) m=M_LINE;
        else if(!strcmp(opt,"list")) m=M_LIST;
        else if(!strcmp(opt,"markdown")) m=M_MARKDOWN;
        else if(!strcmp(opt,"quote")) m=M_QUOTE;
        else if(!strcmp(opt,"table")) m=M_TABLE;
        else if(!strcmp(opt,"tabs")) m=M_TABS;
