      else {
        if(nSql>=capSql){ capSql=capSql?capSql*2:8; sqlArgs=xrealloc(sqlArgs,sizeof(ArgItem)*capSql); }
        sqlArgs[nSql].str=arg; sqlArgs[nSql].idx=i; nSql++;
      }
    }
  }
