  }
  // script file
  if(scriptFile && !g.stopProcessing){
    FILE *fp=fopen(scriptFile,"r");
    if(fp){
      SrcCtx sctx; memset(&sctx,0,sizeof(sctx)); sctx.kind=1; sctx.filename=xstrdup(scriptFile); sctx.countErrors=0; sctx.bailCounts=0;
      InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=fp; reader.ctx=&sctx; reader.isPrimary=1; str_init(&reader.sqlBuf);
      process_input(&reader);
      str_free(&reader.sqlBuf); free(sctx.filename); fclose(fp);
    }
  }
  int processedMainInput=0;
  if(!g.stopProcessing && nSql>0){
