      nonceActiveCurrent=noncePending; noncePending=0;
      int rc=process_command_string(sqlArgs[i].str,&sctx);
      nonceActiveCurrent=0;
      if(rc!=0){
        // stop further SQL args
        break;
      }
      // exec_sql_chunk for SQL args returns hadError via rc; for dot commands process_command_string returns rc
      // Also if an error occurred inside chunk but rc... exec returns hadError, process_command_string for SQL returns that.
    }
