    // banner if interactive
    if(g.isInteractive){
      printf("SQLite version " FAKE_VERSION " " FAKE_SOURCE_ID "\n");
      printf("Enter \".help\" for usage hints.\n");
      fflush(stdout);
    }
    SrcCtx ictx; memset(&ictx,0,sizeof(ictx)); ictx.kind=0; ictx.countErrors=1; ictx.bailCounts=1;
    InputReader reader; memset(&reader,0,sizeof(reader)); reader.in=stdin; reader.ctx=&ictx; reader.isPrimary=1; str_init(&reader.sqlBuf);
    process_input(&reader);
    str_free(&reader.sqlBuf);
