# Replace render_query_plan_result implementation
old_start=t.find("static void render_query_plan_result(Result *res){")
old_end=t.find("static void render_explain_result(Result *res){", old_start)
old=t[old_start:old_end]
new='''static void render_query_plan_result(Result *res){
  out_str("QUERY PLAN\\n");
  if(res->nCol<=0) return;
  if(res->nCol<4){
    int col=res->nCol-1;
    for(int r=0;r<res->nRows;r++){ out_str("`--"); out_str(res->rows[r][col].data); out_str("\\n"); }
    return;
  }
  // Build tree by id/parent
  int n=res->nRows;
  int *ids=(int*)xmalloc(sizeof(int)*(n?n:1));
  int *parents=(int*)xmalloc(sizeof(int)*(n?n:1));
  // children lists: for each node keep indices in order of appearance
  for(int i=0;i<n;i++){ ids[i]=atoi(res->rows[i][0].data); parents[i]=atoi(res->rows[i][1].data); }
  // Recursive print using iterative stack with state
  // We will implement a recursive helper via function-like loop: Use stack of frames
  typedef struct { int idx; int childPos; int isLast; int depth; } Frame;
  // Find roots: parent==0 or parent id not found
  int *roots=(int*)xmalloc(sizeof(int)*(n?n:1)); int nRoots=0;
  for(int i=0;i<n;i++){
    int par=parents[i]; int found=0; for(int j=0;j<n;j++) if(ids[j]==par) found=1;
    if(par==0 || !found) roots[nRoots++]=i;
  }
  // For each node, precompute children
  // Use recursion via explicit stack printing in DFS order: Do a recursive traversal using a helper stack of iterators
  // Simple recursive implementation using a local function is not possible in C, so we simulate with stack and printing on entry
  typedef struct { int node; int childIndex; int isLast; } Item;
  Item *stack=(Item*)xmalloc(sizeof(Item)*(n+16)); int sp=0;
  // Push roots in reverse order
  for(int i=nRoots-1;i>=0;i--){ stack[sp].node=roots[i]; stack[sp].childIndex=-1; stack[sp].isLast=(i==nRoots-1); sp++; }
  // To print prefix correctly we need ancestor isLast chain. Maintain array ancIsLast by depth: we can store depth and a copy of ancestor flags in each stack item as a bitmask (depth up to 32)
  // Extend Item with depth and ancMask (bit i = ancestor at level i is last)
  // We'll redo stack as struct with fields; simpler: do a recursive traversal using manual stack of structs containing ancMask
  // Re-define:
  // (We will use a second stack implementation below; the above stack will be discarded)
  free(stack);
  {
    typedef struct { int node; int childStage; int isLast; unsigned int ancMask; int depth; } SFrame;
    SFrame *st=(SFrame*)xmalloc(sizeof(SFrame)*(n+16));
    int sp2=0;
    for(int i=nRoots-1;i>=0;i--){ st[sp2].node=roots[i]; st[sp2].childStage=0; st[sp2].isLast=(i==nRoots-1); st[sp2].ancMask=0; st[sp2].depth=0; sp2++; }
    while(sp2>0){
      SFrame *fr=&st[sp2-1];
      int node=fr->node;
      if(fr->childStage==0){
        // print this node
        // prefix from ancestors: depth is fr->depth, ancMask bit (depth-1?) For each level 0..depth-1, ancestor isLast flag stored in ancMask bit level
        for(int lvl=0;lvl<fr->depth;lvl++){
          int ancLast = (fr->ancMask>>lvl)&1;
          out_str(ancLast?"   ":"|  ");
        }
        out_str(fr->isLast?"`--":"|--");
        out_str(res->rows[node][3].data);
        out_str("\\n");
      }
      // find next child
      int foundChild=-1; int childCount=0; int foundChildIsLast=0;
      // count children
