  str_addc(&out,'.');
  str_add(&out,pos);
  return out.buf;
}
static char *display_schema_name(const char *schema,const char *name){
  if(!strcmp(schema,"main")) return xstrdup(name);
  return strdup_printf("%s.%s",schema,name);
