    Str sel; str_init(&sel);
    if(includeRowid) str_add(&sel,"_rowid_");
    int firstCol= includeRowid?0:1;
    // Column names list for insert and select
    Str colNames; str_init(&colNames);
    if(includeRowid) str_add(&colNames,"_rowid_");
    for(int c=0;c<cols.nRows;c++){
      if(atoi(cols.rows[c][6].data)!=0) continue; // hidden/generated
      const char *cname=cols.rows[c][1].data;
      if(colNames.len>0) str_add(&colNames,", ");
      // Insert list uses single-quoted names, select uses quoted ident
      // We'll build colNames for insert separately below, sel is select list
      // sel addition
      if(sel.len>0) str_add(&sel,", ");
      char *cq=quote_ident(cname); str_add(&sel,cq); free(cq);
