    // Table single quoted name
    Str tq; str_init(&tq); str_addc(&tq,'\\''); for(const char *pp=tname;*pp;pp++){ if(*pp=='\\'') str_add(&tq,"''"); else str_addc(&tq,*pp); } str_addc(&tq,'\\'');
    for(int r=0;r<data.nRows;r++){
      out_printf("INSERT OR IGNORE INTO %s(%s) VALUES (",tq.buf,insCols.buf);
      for(int c=0;c<data.nCol;c++){ if(c) out_str(", "); char *v=recover_value(&data.rows[r][c]); out_str(v); free(v); }
      out_str(");\\n");
    }
