static void fn_unixepoch(sqlite3_context *ctx,int argc,sqlite3_value **argv){
  sqlite3 *adb=get_aux_db(); if(!adb){ sqlite3_result_null(ctx); return; }
  if(argc==0){ sqlite3_result_int64(ctx,(long long)time(NULL)); return; }
  // Build SELECT strftime('%s', ?, ?, ...)
