  if(sqlite3_prepare_v2(adb,sql.buf,-1,&st,NULL)!=SQLITE_OK){ sqlite3_result_null(ctx); str_free(&sql); return; }
  str_free(&sql);
  for(int i=0;i<argc;i++){
