  if(sqlite3_column_type(st,0)==SQLITE_NULL){ sqlite3_finalize(st); sqlite3_result_null(ctx); return; }
  if(isTextVer){
    int tp=sqlite3_column_type(st,0);
    if(tp==SQLITE_INTEGER) sqlite3_result_int64(ctx,sqlite3_column_int64(st,0));
    else if(tp==SQLITE_FLOAT) sqlite3_result_double(ctx,sqlite3_column_double(st,0));
    else if(tp==SQLITE_BLOB) sqlite3_result_blob(ctx,sqlite3_column_blob(st,0),sqlite3_column_bytes(st,0),SQLITE_TRANSIENT);
    else { const unsigned char *txt=sqlite3_column_text(st,0); sqlite3_result_text(ctx,(const char*)txt,-1,SQLITE_TRANSIENT); }
    sqlite3_finalize(st); return;
  }else{
    const char *jtype=(const char*)sqlite3_column_text(st,1);
    if(jtype && (!strcmp(jtype,"object")||!strcmp(jtype,"array"))){
      const unsigned char *txt=sqlite3_column_text(st,0); sqlite3_result_text(ctx,(const char*)txt,-1,SQLITE_TRANSIENT);
