      else if(tp==SQLITE_FLOAT) sqlite3_result_double(ctx,sqlite3_column_double(st,0));
      else { const unsigned char *txt=sqlite3_column_text(st,0); sqlite3_result_text(ctx,(const char*)txt,-1,SQLITE_TRANSIENT); }
    }
    sqlite3_finalize(st); return;
  }
}
