  char createStmt[2048]="";
  if(hasScanWithFilter){
    // Build cols joined
    Str cj; str_init(&cj);
    for(int i=0;i<nSug;i++){ if(i) str_add(&cj,", "); str_add(&cj,suggestedCols[i]); }
    snprintf(colsJoined,sizeof(colsJoined),"%s",cj.buf);
