  if(sz==12){ if(pos+1>=len) return 0; *typeOut=type; *payloadLenOut=data[pos+1]; *headerLenOut=2; return 1; }
  if(sz==13){ if(pos+2>=len) return 0; *typeOut=type; *payloadLenOut=(data[pos+1]<<8)|data[pos+2]; *headerLenOut=3; return 1; }
  if(sz==14){ if(pos+4>=len) return 0; *typeOut=type; *payloadLenOut=(data[pos+1]<<24)|(data[pos+2]<<16)|(data[pos+3]<<8)|data[pos+4]; *headerLenOut=5; return 1; }
