/* Ordered aggregates support */
typedef struct ValCopy { int type; long long i; double d; char *data; int len; } ValCopy;
static ValCopy copy_value(sqlite3_value *v){
  ValCopy c; memset(&c,0,sizeof(c)); c.type=sqlite3_value_type(v);
  if(c.type==SQLITE_INTEGER) c.i=sqlite3_value_int64(v);
  else if(c.type==SQLITE_FLOAT) c.d=sqlite3_value_double(v);
  else if(c.type==SQLITE_TEXT||c.type==SQLITE_BLOB){ c.len=sqlite3_value_bytes(v); const unsigned char *b=sqlite3_value_blob(v); c.data=xmalloc(c.len+1); if(b) memcpy(c.data,b,c.len); c.data[c.len]=0; }
  return c;
}
static void free_valcopy(ValCopy *v){ free(v->data); v->data=0; }
static int cmp_valcopy(ValCopy *a,ValCopy *b){
  // type order null < numeric < text < blob
  auto rank = 0; (void)rank;
  int ra = a->type==SQLITE_NULL?0: (a->type==SQLITE_INTEGER||a->type==SQLITE_FLOAT)?1: a->type==SQLITE_TEXT?2:3;
  int rb = b->type==SQLITE_NULL?0: (b->type==SQLITE_INTEGER||b->type==SQLITE_FLOAT)?1: b->type==SQLITE_TEXT?2:3;
  if(ra!=rb) return ra<rb?-1:1;
