    if(c=='['){ i++; while(i<end && s[i]!=']') i++; if(i<end) i++; continue; }
    if(c=='('){ depth++; i++; continue; }
    if(c==')'){ depth--; i++; continue; }
    if(depth==0 && (isalpha(c)||c=='_')){
      int ws=i; while(i<end && (isalnum((unsigned char)s[i])||s[i]=='_')) i++;
