def run_both(args,inp,files=None):
    results=[]
    for exe in [ORIG,MINE]:
        d=tempfile.mkdtemp()
        for fn,content in (files or {}).items(): pathlib.Path(os.path.join(d,fn)).write_text(content)
        link=os.path.join(d,"executable"); os.symlink(exe,link)
        r=subprocess.run(["./executable"]+args,input=inp,capture_output=True,cwd=d)
        fdata={}
        for root,dirs,fns in os.walk(d):
            for fn in fns:
                pp=os.path.join(root,fn)
                if os.path.islink(pp): continue
                rel=os.path.relpath(pp,d)
                if rel in (files or {}): continue
                try: fdata[rel]=pathlib.Path(pp).read_bytes()
                except: pass
        results.append((r.returncode,r.stdout,r.stderr,fdata))
        shutil.rmtree(d,ignore_errors=True)
    return results

